    "tour1Title": "Pick a sample photo",
    "tour1Body": "Each sample starts dark, flat or grainy, like a straight-from-camera file. Choose one to edit.",
    "tour2Title": "Light",
    "tour2Body": "Exposure, contrast, highlights, shadows, whites and blacks. Drag a slider or use the arrow keys. Select the number to reset it.",
