    "rawFuji": "Fujifilm (most bodies)",
    "rawTitle": "Opens RAW files from",
    "rawListLabel": "Camera makers whose RAW files are tested",
    "rawAlso": "Also opens Samsung, Hasselblad, Phase One, Leica and Leaf RAW files. These are new, so not every body has been tested yet.",
    "matrixCloudBasic": "Not included",
    "matrixCloudPro": "500 a month",
    "matrixRowCloudRunner": "Cloud edits, when signed in: some heavy steps (today classic noise reduction and upscaling) run in the cloud, and the copy sent is deleted after each run",
    "matrixStoragePro": "2.5 GB",
    "matrixRowStorage": "Cloud storage, to open your photos on your other devices",
    "navHow": "How it works",
    "navShoot": "On a shoot",
    "navPlans": "Plans",
    "signIn": "Sign in",
    "heroHeadline": "Cull, edit and share a shoot. Even with no signal.",
    "heroLeadNew": "InFlight sorts a shoot, edits it and exports it at every size you post at, and never touches your originals. Every edit can be undone, and the Mac and Windows apps work fully offline, with no account needed.",
    "welcomeTitle": "Welcome to InFlight",
    "inviteOnly": "By invitation only while we test.",
    "platformsNote": "InFlight is for macOS, Windows, Linux, iOS and Android, and has no web editor. A platform has a download only when its button appears below; the rest are coming soon. It works offline, with no account.",
    "requestInvite": "Request an invitation",
    "promiseLabel": "What InFlight promises",
    "promiseAiTitle": "No generated pixels.",
    "promiseAiBody": "InFlight never invents or replaces what’s in your photo, and never writes model-made content into your files’ metadata. Your originals are never changed. Models measure and suggest (subject, focus, species, noise). Noise reduction and sharpening work from your photo’s own pixels; the optional learned noise reduction only cleans the pixels already there, and is used only when a check shows real detail survived. The one exception is Spot healing, which copies from elsewhere in your own photo, and only where you place it yourself.",
    "promiseYoursTitle": "Your photos stay yours.",
    "promiseYoursBody": "Originals are never changed or moved, and nothing is uploaded unless you choose to share.",
    "promiseSocialTitle": "Share to social with ease.",
    "promiseSocialBody": "One edit exports every crop and size you post at, ready for each platform.",
    "promiseCollabTitle": "Cloud help, when you want it.",
    "promiseCollabBody": "Send photos for cloud edits when your device needs a hand: 500 a month on Pro, 5,000 on Pro Plus, then 0.3p each from Cloud Credit. The copy sent is deleted after each run. Pro also keeps 2.5 GB of chosen photos in the cloud, to open on your other devices.",
    "whyTitle": "Why photographers switch to InFlight",
    "why3Title": "Same app on every device",
    "why3Body": "Mac, Windows and Linux share one set of screens, and the iPhone, iPad and Android apps, still to come, will be built from the same code, so nothing has to be learned twice.",
    "why4Title": "Honest about your photos",
    "why4Body": "No generated pixels and no invented detail. When it isn't sure of a species or a color, it says so, in words, never by color alone.",
    "howTitle": "How it works",
    "how1Title": "1. Bring your photos in",
    "how1Body": "Point InFlight at a card or folder. It links to your originals and never moves, renames or rewrites them.",
    "how2Title": "2. Keep the best",
    "how2Body": "Flag, rate and compare. Unsure photos are kept for review, never thrown away for you.",
    "how3Title": "3. Edit, and undo anything",
    "how3Body": "Every change is a recipe you can step back through. On-device tools work offline, with nothing uploaded.",
    "how4Title": "4. Export and share",
    "how4Body": "Full-size exports, ready for print, the web or social media.",
    "shootTitle": "Made for the shoot, too",
    "shootModesTitle": "Flight modes",
    "shootModesBody": "Choose how much InFlight does for you, project by project. It runs on your device, and nothing changes without a clear way back.",
    "shootBrandTitle": "Your brand on every export",
    "shootBrandBody": "Save a brand kit once. Export then puts its logo, colors and text style on every photo in one step. It stays on your device.",
    "insideTitle": "What's inside",
    "inCullTitle": "Smart culling",
    "inSubjectTitle": "Subject identification",
    "inSubjectBody": "Names bird species and tags aircraft and vehicles, so you can search a shoot by what is in it. When it isn't sure, it says so.",
    "inSocialTitle": "Social formats",
    "inSocialBody": "Set up the crops and sizes you post at, once. One edit then exports to every format, each with its own crop.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Color notes measured from the photo itself, not your screen, and told in plain words. Color-blind photographers can edit with confidence.",
    "inMaskTitle": "Masking, before and after, denoise",
    "inMaskBody": "Adjust just part of a photo, compare before and after, and clean up noise. Nothing is generated: no invented pixels.",
    "inOverlayTitle": "Custom overlays and watermarks",
    "inOverlayBody": "Save your logo, colors and text style as a brand kit, and Export puts them on every photo in one step.",
    "whoTitle": "Who it's for",
    "whoBody": "Anyone: beginners, pros, or just for fun. Every on-device tool is free, with no limit.",
    "whoListLabel": "Made for",
    "whoLevels": "Beginners and pros",
    "whoColour": "Color-blind photographers",
    "whoNeuro": "Neurodivergent photographers",
    "whoWildlife": "Wildlife",
