    "basicOwn": "<strong>Download it and it's yours.</strong> Basic never expires and needs no account",
    "basicOffline": "Import, cull, edit and export, fully offline",
    "basicModels": "Every on-device model and tool, including species ID and smart culling",
    "priceYear": "a year",
    "priceOr": "or",
    "priceMonthCancel": "a month, cancel any time",
    "proEverything": "Everything in Basic",
    "proCloud": "Cloud edits: 500 photos a month",
    "plusCloud": "Cloud edits: 5,000 photos a month",
    "plusTitle": "Pro Plus",
    "plusEverything": "Everything in Pro",
    "proStorage": "2.5 GB of cloud storage, to open and edit chosen photos on your other devices",
    "plusStorage": "10 GB of cloud storage, to open and edit chosen photos on your other devices",
    "creditTitle": "Pay as you go Cloud Storage",
    "creditBody": "Keep more photos in the cloud for your other devices, and send more for cloud edits. Pay only for what you use beyond what's included. Top up from £5, or let it top up automatically when your balance runs low. Credit rolls over from month to month.",
