    "heroTitle": "Mwy o amser y tu ôl i’r camera.",
    "heroLead": "Mae InFlight yn weithle lluniau ar gyfer mewnforio, didoli, golygu ac allforio. Ei nod yw gwneud golygu’n gyflymach ac yn haws ei ddeall: dewis eich lluniau gorau, gwneud ychydig o olygiadau y gallwch eu dilyn, ac allforio.",
