    "aimOfflineTitle": "Gweithio all-lein",
    "aimOfflineBody": "Mewnforio, didoli, golygu ac allforio heb gysylltiad â’r rhyngrwyd na chyfrif. Mae’ch lluniau’n aros ar eich dyfais neu yn y storfa a ddewiswch.",
    "aimOriginalsTitle": "Byth newid eich ffeiliau gwreiddiol",
    "aimOriginalsBody": "Dydy InFlight ddim yn newid, symud na disodli ffeil wreiddiol. Mae golygiadau’n cael eu cadw fel camau y gallwch eu newid neu eu dadwneud unrhyw bryd.",
    "aimCalmTitle": "Aros yn dawel ac yn hygyrch",
    "aimCalmBody": "Sgrin dawel, geiriau plaen, mynediad llawn drwy’r bysellfwrdd a llai o symud. Does dim yn dibynnu ar liw yn unig. Mae wedi’i gynllunio gyda ffotograffwyr lliwddall, ffotograffwyr ag ADHD a ffotograffwyr awtistig mewn golwg.",
    "aimHonestTitle": "Bod yn onest am yr hyn mae’n ei wybod",
    "aimHonestBody": "Pan nad yw InFlight yn siŵr, mae’n dweud hynny. Mae’n dweud wrthych pan fydd yn dangos rhagolwg mewnol ffeil RAW, dydy e byth yn dyfeisio manylder, ac mae’n cadw lluniau ansicr i chi eu hadolygu yn lle eu gwrthod.",
