    "downloadsIntro": "Mae InFlight yn cael ei ddatblygu. Dim ond ar ôl i fersiwn cyfatebol o’r ap gael ei gyhoeddi y bydd gosodwyr yn ymddangos yma. Dydy ffeiliau model ac archifau cod ffynhonnell ddim yn osodwyr ap.",
