    "installTitle": "Gosod InFlight",
    "installIntro": "Dydy fersiynau cynnar ddim wedi’u llofnodi gan Apple na Microsoft eto, felly bydd pob system yn gofyn i chi gadarnhau cyn eu hagor y tro cyntaf. Lawrlwythwch o’r dudalen hon yn unig.",
    "installNote": "Dydy gosod na defnyddio InFlight byth yn newid nac yn uwchlwytho’ch ffotograffau. Bydd gosodwyr wedi’u llofnodi yn disodli’r camau hyn mewn fersiwn diweddarach.",
    "chooseTitle": "Dewiswch sut i ddechrau",
    "chooseFreeTitle": "Defnyddiwch Basic am ddim, neu mewngofnodwch",
    "chooseFreeBody": "Mae Basic am ddim am byth ac nid oes angen cyfrif. Mewnforio, dethol, golygu ac allforio ar eich dyfais eich hun, all-lein.",
    "chooseFreeGet": "Cael Basic",
    "chooseSignIn": "Oes gennych gyfrif yn barod? Mewngofnodwch o ap InFlight. Mae unrhyw drwydded a brynwyd gennych yn cael ei hychwanegu at y ddyfais honno pan fyddwch yn mewngofnodi.",
    "chooseProTitle": "Tanysgrifio i Pro",
    "promoBanner": "Cynnig Dydd Gwener Du: mae Pro yn costio llai pan fyddwch yn mewngofnodi ac yn prynu erbyn diwedd {lastDay}. Mae’r dudalen dalu yn dangos y pris gostyngol cyn i chi dalu.",
    "chooseSubBody": "Talwch bob mis neu bob blwyddyn a chanslo unrhyw bryd. Os byddwch yn stopio, bydd eich cyfrif yn mynd yn ôl i Basic, sydd am ddim: ni fydd eich prosiectau, golygiadau ac allforion byth yn cael eu cloi.",
    "choosePricePromise": "Addewid pris: ni fydd pris eich tanysgrifiad byth yn codi heb o leiaf 30 diwrnod o rybudd drwy e-bost, a dim ond wrth adnewyddu ar ôl y rhybudd hwnnw y bydd pris newydd yn dechrau. Gallwch ganslo cyn hynny.",
    "chooseBuyHow": "I danysgrifio, mewngofnodwch o ap InFlight a dewis Tanysgrifio i Pro. Paddle, ein hailwerthwr, sy’n rhedeg y talu.",
    "chooseTeamTitle": "Timau a sefydliadau",
    "chooseTeamBody": "Mae Enterprise yn cael ei brisio fesul sedd, gydag un bil i’ch sefydliad. Dywedwch wrthym faint o bobl sydd ei angen ac fe anfonwn ddyfynbris.",
    "chooseTeamContact": "Cysylltu â ni am Enterprise",
    "pricingTitle": "Prisiau",
    "freeTitle": "Basic",
    "freePill": "Wrth brofi",
    "freeBody": "Mewnforio, didoli, golygu ac allforio ar eich cyfrifiadur eich hun, all-lein.",
    "proTitle": "Pro",
    "priceTax": "Prisiau’r DU, gan gynnwys TAW. Mae Paddle yn dangos y pris yn eich arian chi, gydag unrhyw dreth ar gyfer eich gwlad, cyn i chi dalu.",
    "reqTitle": "Gofynion system",
    "startTitle": "Dechrau arni",
    "devicesTitle": "Eich lluniau, eich storfa, eich dyfeisiau",
    "privacyTitle": "Mae’ch ffotograffau’n aros yn eiddo i chi",
    "privacyBody": "Mae InFlight yn lleol yn gyntaf. Mewnforiwch, didolwch a golygwch heb gyfrif. Rhaid troi unrhyw ddadansoddi ar-lein dewisol neu nodweddion cwmwl yn y dyfodol ymlaen yn fwriadol. Dydy’ch ffeiliau gwreiddiol ddim yn cael eu huwchlwytho’n dawel.",
    "contactTitle": "Cysylltu â InFlight",
    "contactName": "Enw",
    "contactEmail": "E-bost",
    "contactMessage": "Neges",
    "contactConsent": "Caiff InFlight storio fy e-bost a’m neges er mwyn ateb.",
    "contactSend": "Anfon neges",
    "footerText": "InFlight · Cyn rhyddhau",
    "footerReport": "Rhoi gwybod am broblem",
    "demoDisclaimer": "<strong>Demo o’r offer yw hwn, nid yr ap llawn.</strong> Mae’n defnyddio delweddau enghreifftiol bach a rhagolwg symlach, nid peiriant RAW InFlight. Mae lleihau sŵn a dewis y testun yn cael eu dangos gyda fersiynau parod o bob enghraifft.",
    "installMac": "Agorwch y ddelwedd ddisg a lawrlwythwyd a llusgwch InFlight i Applications. Y tro cyntaf, de-gliciwch InFlight, dewiswch <strong>Open</strong>, yna <strong>Open</strong> eto.",
    "installWindows": "Rhedwch y gosodwr. Os yw Windows yn dweud ei fod wedi diogelu’ch PC, dewiswch <strong>More info</strong>, yna <strong>Run anyway</strong>.",
    "pricingIntro": "<strong>Mae Basic am ddim am byth.</strong> Tanysgrifiad yw Pro, wedi’i dalu bob mis neu bob blwyddyn. Rydych yn tanysgrifio o ap InFlight; nid yw’r wefan hon yn cymryd taliadau ei hun.",
    "reqMac": "<strong>macOS:</strong> i’w gadarnhau ar ôl i’r fersiwn cyntaf gael ei brofi ar Macs go iawn (wedi’i adeiladu ar gyfer Apple silicon ac Intel).",
    "reqWindows": "<strong>Windows:</strong> i’w gadarnhau ar ôl i’r fersiwn cyntaf gael ei brofi ar PCs go iawn.",
    "reqStorage": "<strong>Storfa:</strong> lle i’r model rhywogaethau dewisol ar y ddyfais (tua 90 MB) a’ch catalog. Gall ffeiliau gwreiddiol aros ar yriannau allanol.",
    "startImport": "<strong>Mewnforio:</strong> dewiswch ffotograffau neu ffolder sydd ar eich dyfais. Cadwch gopi wrth gefn ar wahân o’ch ffeiliau gwreiddiol.",
    "startCull": "<strong>Didoli:</strong> adolygwch ffotograffau, marciwch Cadw neu Gwrthod, a chymharwch fframiau cyfagos.",
    "startEdit": "<strong>Golygu:</strong> addaswch y golau, y lliw a’r tocio. Gellir dadwneud golygiadau, a dydyn nhw ddim yn ailysgrifennu’r ffeil wreiddiol.",
    "startExport": "<strong>Allforio:</strong> dewiswch fformat a chadwch y ffotograff terfynol.",
    "nikonNote": "<strong>Nodyn am RAW Nikon:</strong> Ar hyn o bryd mae trin NEF yn y porwr yn dibynnu ar ragolygon mewnol. Rhaid dilysu datgodio RAW cydraniad llawn, gan gynnwys amrywiadau High Efficiency Nikon, mewn fersiynau brodorol cyn ei hysbysebu fel nodwedd sy’n cael ei chefnogi.",
    "devicesAnywhere": "<strong>Cadw lluniau unrhyw le:</strong> ar unrhyw yriant, NAS, neu ffolder sy’n cael ei gysoni gan iCloud Drive, Dropbox neu OneDrive. Dydy InFlight byth yn symud nac yn newid eich ffeiliau gwreiddiol.",
    "devicesCopy": "<strong>Copïo gosodiadau i ddyfais arall:</strong> dewiswch <em>Cadw ffeil gosodiadau</em> a’i chadw yn iCloud Drive, yna dewiswch <em>Llwytho ffeil gosodiadau</em> ar eich Mac, PC neu ffôn arall.",
