    "tour1Title": "Dewis llun enghreifftiol",
    "tour1Body": "Mae pob enghraifft yn dechrau’n dywyll, yn fflat neu’n graenog, fel ffeil syth o’r camera. Dewiswch un i’w golygu.",
    "tour2Title": "Golau",
    "tour2Body": "Amlygiad, cyferbyniad, uchafbwyntiau, cysgodion, gwynion a duon. Llusgwch lithrydd neu defnyddiwch y bysellau saeth. Dewiswch y rhif i’w ailosod.",
    "tour3Title": "Lliw",
    "tour3Body": "Mae tymheredd ac arlliw yn cywiro gwawr lliw. Mae bywiogrwydd yn codi lliwiau tawel yn gyntaf; mae dirlawnder yn newid pob un.",
    "tour4Title": "Manylder a lleihau sŵn",
    "tour4Body": "Mae eglurder yn ychwanegu cyferbyniad lleol. Demo yw lleihau sŵn yma sy’n newid i ddelwedd lanach barod, nid teclyn lleihau sŵn InFlight.",
    "tour5Title": "Masgio",
    "tour5Body": "Dewiswch y testun, yna golygwch y testun yn unig neu’r cefndir yn unig. Mae’r masg wedi’i baratoi ymlaen llaw ar gyfer pob enghraifft i ddangos sut mae dewis testun yn gweithio.",
