    "matrixRowOnline": "Cynorthwyydd ar-lein dewisol, dim ond pan fyddwch chi'n dewis",
    "matrixNote": "Nid yw Basic byth yn dod i ben ac nid oes angen cyfrif arno. Tanysgrifiad yw Pro; os daw i ben, mae’r cyfrif yn mynd yn ôl i Basic. Nid yw mewnforio, golygu ac allforio byth yn cael eu dal yn ôl, ni chaiff dim a wnaethoch byth ei gloi, ac ni chaiff eich rhai gwreiddiol byth eu newid yn y naill rifyn na’r llall.",
    "proBody": "Mae Pro yn ychwanegu awgrymiadau rhywogaethau, help i ddewis lluniau a’r cynorthwyydd ar-lein dewisol. Mae’n gweithio all-lein: mae dyfais na all wirio yn cadw Pro am hyd at 30 diwrnod ers iddi wirio ddiwethaf, a hyd at 14 diwrnod wedi dyddiad adnewyddu.",
