    "vizHeroLabel": "Braslun mwy o olygydd InFlight. Mae'r pwyntydd yn llusgo'r llithrydd Cysgodion, yna Datguddiad, ac mae'r llun yn goleuo. Mae'r newid yn ymddangos yn Hanes, yna mae Dadwneud yn mynd â'r ddau gam yn ôl.",
