    "vizOriginal": "Nid yw'r gwreiddiol byth yn newid",
    "vizImportLabel": "Mae'r pwyntydd yn llusgo tair ffeil llun i InFlight. Mae bar cynnydd yn rhedeg ar hyd y brig wrth iddynt gael eu hychwanegu ac mae'r mân-luniau'n ymddangos. Mae'r ffeiliau gwreiddiol yn aros lle maen nhw.",
    "vizDrop": "Gollyngwch luniau neu ffolder yma",
    "vizAdded": "24 llun wedi'u hychwanegu",
    "vizCullLabel": "Chwe llun mewn grid, wedi'u dethol â'r bysellfwrdd. Mae F yn marcio'r cyntaf, mae 4 yn rhoi pedair seren i'r ail, mae X yn gwrthod y pedwerydd ac mae F yn marcio'r pumed. Mae'r trydydd llun, un yr oedd InFlight yn ansicr amdano, yn aros wedi'i farcio I'w hadolygu yn lle cael ei daflu.",
    "vizRejected": "Wedi'i wrthod",
    "vizEditLabel": "Mae'r pwyntydd yn codi Bywiogrwydd ac yn gostwng Golau llachar, ac mae'r llun yn newid. Yna caiff Dadwneud ei wasgu ddwywaith, ac mae'r llun yn ôl yn union fel yr oedd.",
    "vizExportLabel": "Panel allforio ar gyfer 24 llun, maint llawn, fel JPEG. Mae'r pwyntydd yn pwyso Allforio, mae bar cynnydd yn llenwi, ac mae'r panel yn dweud bod pob un o'r 24 wedi'u cadw.",
