    "matrixRowCloudRunner": "Golygu yn y cwmwl, wedi mewngofnodi: mae rhai camau trwm (heddiw lleihau sŵn clasurol a chynyddu maint) yn rhedeg yn y cwmwl, a chaiff y copi a anfonwyd ei ddileu ar ôl pob rhediad",
