    "signIn": "Mewngofnodi",
    "heroHeadline": "Dethol, golygu a rhannu sesiwn. Hyd yn oed heb signal.",
    "heroLeadNew": "Mae InFlight yn trefnu saethiad, yn ei olygu ac yn ei allforio ym mhob maint rydych chi'n postio ynddo, a byth yn cyffwrdd â'ch gwreiddiolion. Gellir dadwneud pob golygiad, ac mae'r apiau Mac a Windows yn gweithio'n llwyr all-lein, heb angen cyfrif.",
    "welcomeTitle": "Croeso i InFlight",
    "inviteOnly": "Drwy wahoddiad yn unig tra byddwn yn profi.",
    "platformsNote": "Mae InFlight ar gyfer macOS, Windows, Linux, iOS ac Android, heb olygydd gwe. Dim ond pan fydd ei botwm yn ymddangos isod y mae lawrlwythiad ar gael ar gyfer platfform; mae'r lleill yn dod cyn bo hir. Mae'n gweithio all-lein, heb gyfrif.",
    "requestInvite": "Gofyn am wahoddiad",
    "promiseLabel": "Addewidion InFlight",
    "promiseAiTitle": "Dim picseli wedi'u cynhyrchu.",
    "promiseAiBody": "Nid yw InFlight byth yn dyfeisio nac yn disodli’r hyn sydd yn eich llun, ac nid yw byth yn ysgrifennu cynnwys a wnaed gan fodel ym metadata eich ffeiliau. Nid yw eich gwreiddiolion byth yn cael eu newid. Mae modelau’n mesur ac yn awgrymu (gwrthrych, ffocws, rhywogaeth, sŵn). Mae lleihau sŵn a miniogi’n gweithio o bicseli eich llun ei hun; dim ond glanhau’r picseli sydd yno’n barod y mae’r lleihau sŵn dysgedig dewisol, a dim ond pan fydd gwiriad yn dangos bod manylion go iawn wedi aros y caiff ei ddefnyddio. Yr unig eithriad yw Trwsio smotiau, sy’n copïo o le arall yn eich llun eich hun, a dim ond lle rydych chi’n ei osod eich hun.",
    "promiseYoursTitle": "Mae eich lluniau'n aros yn eiddo i chi.",
    "promiseYoursBody": "Nid yw gwreiddiolion byth yn cael eu newid na'u symud, a does dim yn cael ei lanlwytho oni bai eich bod yn dewis rhannu.",
    "promiseSocialTitle": "Rhannu i'r cyfryngau cymdeithasol yn rhwydd.",
    "promiseSocialBody": "Mae un golygiad yn allforio pob tociad a maint rydych chi'n postio ynddo, yn barod ar gyfer pob platfform.",
    "promiseCollabTitle": "Help yn y cwmwl, pan fyddwch ei eisiau.",
    "promiseCollabBody": "Anfonwch luniau i’w golygu yn y cwmwl pan fydd angen help ar eich dyfais: 500 y mis ar Pro, 5,000 ar Pro Plus, yna 0.3c yr un o Gredyd Cwmwl. Caiff y copi a anfonwyd ei ddileu ar ôl pob rhediad. Mae Pro hefyd yn cadw 2.5 GB o luniau dewisol yn y cwmwl, i’w hagor ar eich dyfeisiau eraill.",
    "whyTitle": "Pam mae ffotograffwyr yn newid i InFlight",
    "why3Title": "Yr un ap ar bob dyfais",
    "why3Body": "Mae Mac, Windows a Linux yn rhannu'r un sgriniau, a bydd yr apiau iPhone, iPad ac Android, sydd i ddod, yn cael eu hadeiladu o'r un cod, felly does dim rhaid dysgu dim ddwywaith.",
    "why4Title": "Gonest am eich lluniau",
    "why4Body": "Dim picseli wedi'u cynhyrchu a dim manylion wedi'u dyfeisio. Pan nad yw'n siŵr o rywogaeth neu liw, mae'n dweud hynny, mewn geiriau, byth drwy liw yn unig.",
    "howTitle": "Sut mae'n gweithio",
    "how1Title": "1. Dewch â'ch lluniau i mewn",
    "how1Body": "Pwyntiwch InFlight at gerdyn neu ffolder. Mae'n cysylltu â'ch gwreiddiolion a byth yn eu symud, eu hailenwi na'u hailysgrifennu.",
    "how2Title": "2. Cadwch y gorau, yn hamddenol",
    "how2Body": "Marciwch, sgoriwch a chymharwch. Caiff lluniau ansicr eu cadw i'w hadolygu, byth eu taflu ar eich rhan.",
    "how3Title": "3. Golygwch, a dadwneud unrhyw beth",
    "how3Body": "Mae pob newid yn rysáit y gallwch gamu'n ôl drwyddi. Mae offer ar y ddyfais yn gweithio all-lein, heb lanlwytho dim.",
    "how4Title": "4. Allforio a rhannu",
    "how4Body": "Allforion maint llawn, yn barod i’w hargraffu, ar gyfer y we neu’r cyfryngau cymdeithasol.",
    "shootTitle": "Wedi'i wneud ar gyfer y sesiwn hefyd",
    "shootModesTitle": "Moddau hedfan",
    "shootModesBody": "Dewiswch faint mae InFlight yn ei wneud i chi, fesul prosiect. Mae'n rhedeg ar eich dyfais, a does dim yn newid heb ffordd glir yn ôl.",
    "shootBrandTitle": "Eich brand ar bob allforiad",
    "shootBrandBody": "Cadwch becyn brand unwaith. Yna mae Allforio yn rhoi ei logo, ei liwiau a'i arddull testun ar bob llun mewn un cam. Mae'n aros ar eich dyfais.",
    "insideTitle": "Beth sydd y tu mewn",
    "inCullTitle": "Dethol clyfar",
    "inSubjectTitle": "Adnabod y gwrthrych",
    "inSubjectBody": "Yn enwi rhywogaethau adar ac yn tagio awyrennau a cherbydau, fel y gallwch chwilio sesiwn yn ôl ei chynnwys. Pan nad yw'n siŵr, mae'n dweud hynny.",
    "inSocialTitle": "Fformatau cymdeithasol",
    "inSocialBody": "Gosodwch y tociadau a'r meintiau rydych chi'n postio ynddynt, unwaith. Yna mae un golygiad yn allforio i bob fformat, pob un â'i docyn ei hun.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Nodiadau lliw wedi'u mesur o'r llun ei hun, nid eich sgrin, ac wedi'u hesbonio mewn geiriau clir. Gall ffotograffwyr lliwddall olygu'n hyderus.",
    "inMaskTitle": "Masgio, cyn ac ar ôl, lleihau sŵn",
    "inMaskBody": "Addaswch ran o lun yn unig, cymharwch cyn ac ar ôl, a glanhewch sŵn. Does dim yn cael ei gynhyrchu: dim picseli wedi'u dyfeisio.",
    "inOverlayTitle": "Troshaenau a dyfrnodau eich hun",
    "inOverlayBody": "Cadwch eich logo, eich lliwiau a'ch arddull testun fel pecyn brand, ac mae Allforio yn eu rhoi ar bob llun mewn un cam.",
    "whoTitle": "Ar gyfer pwy",
    "whoBody": "Unrhyw un: dechreuwyr, gweithwyr proffesiynol, neu am hwyl. Mae pob teclyn ar y ddyfais am ddim, heb derfyn.",
    "whoListLabel": "Wedi'i wneud ar gyfer",
    "whoLevels": "Dechreuwyr a gweithwyr proffesiynol",
    "whoColour": "Ffotograffwyr lliwddall",
