    "priceFree": "Am ddim",
    "basicOwn": "<strong>Lawrlwythwch ef ac mae'n eiddo i chi.</strong> Nid yw Basic byth yn dod i ben ac nid oes angen cyfrif",
    "basicOffline": "Mewnforio, dethol, golygu ac allforio, yn llwyr all-lein",
    "basicModels": "Pob model a theclyn ar y ddyfais, gan gynnwys adnabod rhywogaethau a dethol clyfar",
