    "plusStorage": "10 GB o storfa cwmwl, i agor a golygu lluniau dewisol ar eich dyfeisiau eraill",
    "creditTitle": "Credyd Cwmwl Talu wrth Ddefnyddio",
    "creditBody": "Cadwch fwy o luniau yn y cwmwl ar gyfer eich dyfeisiau eraill, ac anfonwch fwy i’w golygu yn y cwmwl. Talwch dim ond am yr hyn rydych chi'n ei ddefnyddio y tu hwnt i'r hyn sydd wedi'i gynnwys. Ychwanegwch o £5, neu gadewch iddo ychwanegu'n awtomatig pan fydd eich balans yn isel. Mae credyd yn cario drosodd o fis i fis.",
