    "vizHintSolo": "Nid yw InFlight yn gwneud dim nes i chi ofyn. Chi sy'n dethol ac yn golygu.",
    "vizHintCopilot": "Mae cynorthwyydd InFlight ei hun yn awgrymu dewisiadau a golygiadau, fel cynnig dethol ar ôl mewnforio. Chi sy'n cymeradwyo pob un.",
    "vizHintAutopilot": "Mae InFlight yn gwneud y dewisiadau a'r golygiadau y mae'n hyderus amdanynt. Caiff unrhyw beth ansicr ei adael i chi ei adolygu.",
