    "navContact": "Fios thugainn",
    "languageLabel": "Cànan",
    "heroTitle": "Barrachd ùine air cùl a’ chamara.",
    "heroLead": "’S e àite-obrach dhealbhan a th’ ann an InFlight airson ion-phortadh, seòrsachadh, deasachadh agus às-phortadh. Tha e ag amas air deasachadh a dhèanamh nas luaithe is nas fhasa a thuigsinn: lorg na dealbhan as fheàrr, dèan beagan dheasachaidhean as urrainn dhut leantainn, agus às-phortaich.",
    "heroDownloads": "Seall na luchdaidhean a-nuas",
    "heroPricing": "Seall na prìsean",
    "aimsTitle": "Na tha InFlight ag amas air",
    "aimOfflineTitle": "Obraich far loidhne",
    "aimOfflineBody": "Ion-phortaich, seòrsaich, deasaich is às-phortaich gun cheangal ris an eadar-lìon no cunntas. Fanaidh na dealbhan agad air an uidheam agad no san stòras a thaghas tu.",
    "aimOriginalsTitle": "Na h-atharraich na faidhlichean tùsail agad gu bràth",
    "aimOriginalsBody": "Chan atharraich, cha ghluais is cha chuir InFlight faidhle tùsail an àite eile. Thèid deasachaidhean a shàbhaladh mar cheuman as urrainn dhut atharrachadh no a neo-dhèanamh uair sam bith.",
    "aimCalmTitle": "Fuirich socair is so-ruigsinneach",
    "aimCalmBody": "Sgrìn shàmhach, faclan sìmplidh, smachd slàn leis a’ mheur-chlàr agus nas lugha de ghluasad. Chan eil dad an urra ri dath a-mhàin. Chaidh a dhealbhachadh le dealbhadairean dath-dhall, le ADHD agus autistic san amharc.",
    "aimHonestTitle": "Bi onarach mu na tha fios aige",
    "aimHonestBody": "Nuair nach eil InFlight cinnteach, canaidh e sin. Innsidh e dhut nuair a sheallas e an ro-shealladh a tha am broinn faidhle RAW, cha chruthaich e mion-fhiosrachadh gu bràth, agus cumaidh e dealbhan mì-chinnteach dhut airson sgrùdadh seach an diùltadh.",
    "aimHelpTitle": "Cuidich gun smachd a ghabhail",
    "aimHelpBody": "’S urrainn do dh’ionnsachadh innealach cuideachadh le fuaim a lùghdachadh, cuspair a lorg no masg a mholadh. ’S ann agadsa a tha e gach moladh a sgrùdadh is a ghleusadh.",
    "aimSameTitle": "Obraich san aon dòigh anns gach àite",
    "aimSameBody": "Na h-aon innealan agus an aon dòigh obrach air macOS, Windows agus Linux, le iPhone, iPad agus Android gu bhith ann.",
    "aimOnceTitle": "Gun cheangal",
    "aimOnceBody": "Bidh Basic saor ’s an-asgaidh gu bràth. ’S e fo-sgrìobhadh a th’ ann am Pro as urrainn dhut sgur dheth uair sam bith, agus cha tèid dad a rinn thu a ghlasadh ma sguireas tu. Faodaidh luchd-deuchainn le cuireadh Pro fhaighinn an-asgaidh.",
    "demoShowOriginal": "Seall an tùsail",
