    "demoCropNote": "Nì am bearradh sùm a-steach dìreach gu leòr airson oiseanan falamh a sheachnadh nuair a dhìreachas tu.",
    "tourBack": "Air ais",
    "tourNext": "Air adhart",
    "tourFinish": "Crìochnaich",
    "demoCredit": "Chaidh na dealbhan eisimpleir a tharraing le coimpiutair airson an taisbeanaidh seo. Brùth Escape gus an turas a dhùnadh.",
    "downloadsTitle": "Faigh InFlight",
    "downloadsIntro": "Tha InFlight ga leasachadh. Cha nochd stàlaichearan an seo ach às dèidh do sgaoileadh co-fhreagarrach den aplacaid fhoillseachadh. Chan e stàlaichearan aplacaid a th’ ann am faidhlichean modail is tasglannan bun-tùis.",
    "platformDesktop": "Deasachadh air an deasg agus stòras ionadail.",
    "comingSoon": "Ri thighinn a dh’aithghearr",
    "platformIos": "iPhone agus iPad",
    "platformTouch": "Seòrsachadh is deasachadh airson suathadh.",
    "releaseChecking": "A’ lorg luchdaidhean a-nuas foillsichte den aplacaid…",
    "installTitle": "A’ stàladh InFlight",
    "installIntro": "Cha deach na tionndaidhean tràtha a shoidhneadh le Apple no Microsoft fhathast, mar sin iarraidh gach siostam ort dearbhadh mus fhosgail thu e a’ chiad turas. Na luchdaich a-nuas ach on duilleag seo.",
    "installNote": "Cha tèid na dealbhan agad atharrachadh no a luchdadh suas gu bràth le bhith a’ stàladh no a’ cleachdadh InFlight. Thèid stàlaichearan soidhnichte an àite nan ceumannan seo ann an sgaoileadh nas fhaide air adhart.",
    "chooseTitle": "Tagh mar a thòisicheas tu",
    "chooseFreeTitle": "Cleachd Basic an-asgaidh, no clàraich a-steach",
    "chooseFreeBody": "Tha Basic an-asgaidh gu bràth agus chan fheum e cunntas. Ion-phortaich, tagh, deasaich is às-phortaich air an uidheam agad fhèin, far loidhne.",
    "chooseFreeGet": "Faigh Basic",
    "chooseSignIn": "A bheil cunntas agad mu thràth? Clàraich a-steach on aplacaid InFlight. Thèid cead sam bith a cheannaich thu a chur ris an uidheam sin nuair a chlàraicheas tu a-steach.",
    "chooseProTitle": "Fo-sgrìobh gu Pro",
    "promoBanner": "Tairgse Dihaoine Dubh: tha Pro nas saoire nuair a chlàraicheas tu a-steach is a cheannaicheas tu ro dheireadh {lastDay}. Seallaidh an t-ionad-pàighidh a’ phrìs nas ìsle mus pàigh thu.",
    "chooseSubBody": "Pàigh gach mìos no gach bliadhna is sguir dheth uair sam bith. Ma sguireas tu, tillidh an cunntas agad gu Basic, a tha saor ’s an-asgaidh: cha tèid na pròiseactan, na deasachaidhean no na h-às-phortaidhean agad a ghlasadh gu bràth.",
    "choosePricePromise": "Gealladh prìse: chan èirich prìs an fho-sgrìobhaidh agad gu bràth gun 30 latha de rabhadh air a’ char as lugha air post-d, agus cha tòisich prìs ùr ach aig ath-nuadhachadh às dèidh an rabhaidh sin. Faodaidh tu sgur roimhe sin.",
    "chooseBuyHow": "Airson fo-sgrìobhadh, clàraich a-steach on aplacaid InFlight is tagh Fo-sgrìobh gu Pro. ’S e Paddle, an ath-reiceadair againn, a ruitheas am pàigheadh.",
    "chooseTeamTitle": "Sgiobaidhean is buidhnean",
    "chooseTeamBody": "Tha prìs Enterprise a-rèir suidheachain, le aon bhile airson na buidhne agad. Innis dhuinn cia mheud duine a dh’fheumas e is cuiridh sinn tairgse-phrìse thugad.",
    "chooseTeamContact": "Cuir fios thugainn mu Enterprise",
    "pricingTitle": "Prìsean",
    "freeTitle": "Basic",
    "freePill": "Fhad ’s a tha e ga dheuchainn",
    "freeBody": "Ion-phortaich, seòrsaich, deasaich is às-phortaich air a’ choimpiutair agad fhèin, far loidhne.",
    "proTitle": "Pro",
    "priceTax": "Prìsean na RA, a’ gabhail a-steach VAT. Seallaidh Paddle a’ phrìs nad airgead fhèin, le cìs sam bith airson na dùthcha agad, mus pàigh thu.",
    "reqTitle": "Riatanasan an t-siostaim",
    "startTitle": "Toiseach tòiseachaidh",
    "devicesTitle": "Na dealbhan agad, an stòras agad, na h-uidheaman agad",
    "privacyTitle": "’S ann leatsa a bhios na dealbhan agad",
    "privacyBody": "Tha InFlight ionadail an toiseach. Ion-phortaich, seòrsaich is deasaich gun chunntas. Feumar mion-sgrùdadh air loidhne roghainneil no gleusan neòil san àm ri teachd a chur air a dh’aon ghnothach. Cha tèid na faidhlichean tùsail agad a luchdadh suas gun fhiosta.",
    "contactTitle": "Cuir fios gu InFlight",
    "contactName": "Ainm",
    "contactEmail": "Post-d",
    "contactMessage": "Teachdaireachd",
    "contactConsent": "Faodaidh InFlight am post-d is an teachdaireachd agam a stòradh gus freagairt.",
    "contactSend": "Cuir an teachdaireachd",
    "footerText": "InFlight · Ro-sgaoileadh",
    "footerReport": "Dèan aithris air duilgheadas",
    "demoDisclaimer": "<strong>Seo taisbeanadh de na h-innealan, chan e an aplacaid shlàn.</strong> Tha e a’ cleachdadh dhealbhan eisimpleir beaga agus ro-shealladh nas sìmplidhe, chan e einnsean RAW InFlight. Thèid lùghdachadh gràinne is taghadh a’ chuspair a shealltainn le tionndaidhean ro-dhèanta de gach eisimpleir.",
    "installMac": "Fosgail an ìomhaigh diosga a luchdaich thu a-nuas agus slaod InFlight gu Applications. A’ chiad turas, dèan briogadh deas air InFlight, tagh <strong>Open</strong>, agus an uairsin <strong>Open</strong> a-rithist.",
    "installWindows": "Ruith an stàlaichear. Ma chanas Windows gun do dhìon e am PC agad, tagh <strong>More info</strong>, agus an uairsin <strong>Run anyway</strong>.",
    "pricingIntro": "<strong>Tha Basic saor ’s an-asgaidh gu bràth.</strong> ’S e fo-sgrìobhadh a th’ ann am Pro, air a phàigheadh gach mìos no gach bliadhna. Nì thu fo-sgrìobhadh on aplacaid InFlight; cha ghabh an làrach-lìn seo fhèin ri pàighidhean.",
    "reqMac": "<strong>macOS:</strong> ri dhearbhadh nuair a bhios a’ chiad tionndadh air a dheuchainn air fìor Macs (air a thogail airson Apple silicon agus Intel).",
    "reqWindows": "<strong>Windows:</strong> ri dhearbhadh nuair a bhios a’ chiad tionndadh air a dheuchainn air fìor PCs.",
    "reqStorage": "<strong>Stòras:</strong> àite airson modail roghainneil nan gnèithean air an uidheam (mu 90 MB) agus an catalog agad. Faodaidh na faidhlichean tùsail fuireach air draibhean taobh a-muigh.",
    "startImport": "<strong>Ion-phortaich:</strong> tagh dealbhan no pasgan a tha air an uidheam agad. Cùm lethbhreac-glèidhidh fa leth de na faidhlichean tùsail agad.",
    "startCull": "<strong>Seòrsaich:</strong> thoir sùil air dealbhan, comharraich Cùm no Diùlt, agus dèan coimeas eadar frèamaichean faisg air a chèile.",
    "startEdit": "<strong>Deasaich:</strong> gleus an solas, an dath is am bearradh. Gabhaidh deasachaidhean an neo-dhèanamh agus cha sgrìobh iad thairis air an fhaidhle thùsail.",
    "startExport": "<strong>Às-phortaich:</strong> tagh fòrmat agus sàbhail an dealbh deiseil.",
    "nikonNote": "<strong>Nòta mu RAW Nikon:</strong> An-dràsta, tha làimhseachadh NEF sa bhrabhsair an urra ri ro-shealladh a tha am broinn an fhaidhle. Feumar dì-chòdachadh RAW aig làn-dùmhlachd, a’ gabhail a-steach tionndaidhean High Efficiency aig Nikon, a dhearbhadh ann an tionndaidhean dùthchasach mus tèid a shanasachd mar rud a tha taic ann dha.",
    "devicesAnywhere": "<strong>Cùm dealbhan an àite sam bith:</strong> air draibh sam bith, NAS, no pasgan a thèid a shioncronachadh le iCloud Drive, Dropbox no OneDrive. Cha ghluais is chan atharraich InFlight na faidhlichean tùsail agad gu bràth.",
    "devicesCopy": "<strong>Lethbhreacaich roghainnean gu uidheam eile:</strong> tagh <em>Sàbhail faidhle nan roghainnean</em> agus sàbhail e ann an iCloud Drive, an uairsin tagh <em>Luchdaich faidhle nan roghainnean</em> air a’ Mhac, PC no fòn eile agad.",
    "navHome": "Dachaigh InFlight",
    "navLabel": "Prìomh sheòladh",
    "demoShowOriginalHint": "Cùm sìos gus an tùsail fhaicinn",
    "demoDivider": "Roinneadair roimhe is às dèidh: tha roimhe air an taobh chlì",
    "demoPhotos": "Dealbhan eisimpleir",
    "demoTools": "Innealan deasachaidh",
    "tourClose": "Dùin an turas treòraichte",
    "pageTitle": "InFlight — Tagh, deasaich is co-roinn seisean, fiù far loidhne.",
    "metaDescription": "Taghaidh, deasaichidh is co-roinnidh InFlight na dealbhan agad, fiù gun chomharra. Gun piogsailean air an gineadh, chan atharraichear na tùsan agad gu bràth, agus tha Basic saor 's leatsa ri chumail.",
    "suggested": "★ Air a mholadh airson an uidheim seo",
