    "releaseNotYet": "Cha deach InFlight fhoillseachadh fhathast. Nochdaidh stàlaichearan an seo nuair a bhios a’ chiad sgaoileadh deiseil.",
    "releaseShowing": "A’ sealltainn InFlight {version}. Tha SHA-256 gach faidhle ann an SHA256SUMS.txt ri thaobh.",
