    "tour1Title": "Tagh dealbh eisimpleir",
    "tour1Body": "Tòisichidh gach eisimpleir dorcha, rèidh no gràinneach, mar fhaidhle dìreach on chamara. Tagh fear airson a dheasachadh.",
    "tour2Title": "Solas",
    "tour2Body": "Nochdadh, iomsgaradh, àrd-sholais, faileasan, geala agus dubha. Slaod sleamhnachan no cleachd na h-iuchraichean-saighde. Tagh an àireamh gus ath-shuidheachadh.",
    "tour3Title": "Dath",
    "tour3Body": "Ceartaichidh teòthachd is fiamh dathan ceàrr. Togaidh beòthalachd dathan mùchte an toiseach; atharraichidh sàthachd iad uile.",
    "tour4Title": "Mion-fhiosrachadh is lùghdachadh gràinne",
    "tour4Body": "Cuiridh follaiseachd iomsgaradh ionadail ris. ’S e taisbeanadh a th’ anns an lùghdachadh gràinne an seo a sheallas dealbh nas glaine ro-dhèanta, chan e inneal lùghdachaidh gràinne InFlight.",
    "tour5Title": "Masgadh",
    "tour5Body": "Tagh an cuspair, an uairsin deasaich an cuspair a-mhàin no an cùlaibh a-mhàin. Tha am masg ro-dhèanta airson gach eisimpleir gus sealltainn mar a dh’obraicheas taghadh cuspair.",
    "tour6Title": "Bearr is dèan dìreach",
    "tour6Body": "Tagh cumadh agus dèan am fàire còmhnard.",
    "tour7Title": "Roimhe is às dèidh",
    "tour7Body": "Cuir an sgaradh air agus slaod an roinneadair, no cùm sìos “Seall an tùsail”. ’S e reasabaidh a th’ anns na deasachaidhean agad, mar sin chan atharraichear an tùsail gu bràth.",
    "walkPlay": "Cluich an sealladh ceum air cheum",
    "walkStop": "Stad an sealladh ceum air cheum",
    "walkLabel": "Ceum air cheum",
    "walk1": "A’ soillseachadh an deilbh le nochdadh",
    "walk2": "A’ fosgladh nam faileasan is a’ ciùineachadh nan àrd-sholas",
    "walk3": "A’ cur beagan blàiths is beòthalachd ris",
    "walk4": "A’ lùghdachadh gràinne (taisbeanadh) is a’ cur follaiseachd ris",
    "walk5": "A’ taghadh a’ chuspair (masg ro-dhèanta)",
    "walk6": "A’ soillseachadh a’ chuspair a-mhàin",
    "walk7": "A’ feuchainn bearradh 4:5",
    "walk8": "A’ dèanamh coimeas eadar roimhe is às dèidh",
    "walk9": "Do thuras-sa: atharraich sleamhnachan sam bith.",
