    "priceFree": "Saor",
    "basicOwn": "<strong>Luchdaich a-nuas e agus 's leatsa e.</strong> Cha tig Basic gu crìch gu bràth agus chan fheum e cunntas",
    "basicOffline": "Ion-phortaich, tagh, deasaich is às-phortaich, gu tur far loidhne",
    "basicModels": "Gach modail is inneal air an uidheam, a' gabhail a-steach aithneachadh ghnèithean agus taghadh glic",
