    "plusCloud": "Deasachadh san neul: 5,000 dealbh sa mhìos",
    "plusTitle": "Pro Plus",
    "plusEverything": "Gach rud ann am Pro",
    "proStorage": "2.5 GB de stòras neòil, airson dealbhan taghte fhosgladh is a dheasachadh air na h-uidheaman eile agad",
    "plusStorage": "10 GB de stòras neòil, airson dealbhan taghte fhosgladh is a dheasachadh air na h-uidheaman eile agad",
    "creditTitle": "Creideas Neòil a-rèir cleachdaidh",
    "creditBody": "Cùm barrachd dhealbhan san neul airson nan uidheaman eile agad, agus cuir barrachd airson deasachadh san neul. Na pàigh ach airson na chleachdas tu thar na tha na bhroinn. Cuir creideas ris o £5, no leig leis a chur ris gu fèin-obrachail nuair a bhios an cothromachadh agad ìosal. Thèid creideas a ghiùlan air adhart bho mhìos gu mìos.",
