    "vizAutopilot": "Fèin-phìleat",
    "vizHintSolo": "Cha dèan InFlight dad gus an iarr thu e. Taghaidh agus deasaichidh tu fhèin.",
    "vizHintCopilot": "Molaidh an cuidiche aig InFlight fhèin taghaidhean is deasachaidhean, can taghadh às dèidh ion-phortaidh. Aontaichidh tu ri gach fear.",
    "vizHintAutopilot": "Cuiridh InFlight an sàs na taghaidhean is na deasachaidhean a tha e cinnteach asta. Thèid rud sam bith mì-chinnteach fhàgail dhut airson lèirmheas.",
