    "demoCredit": "Tarraingíodh na grianghraif shamplacha le ríomhaire don taispeántas seo. Brúigh Escape chun an turas a dhúnadh.",
    "downloadsTitle": "Faigh InFlight",
    "downloadsIntro": "Tá InFlight á fhorbairt. Ní thaispeánfar suiteálaithe anseo go dtí go mbeidh eisiúint aipe a mheaitseálann foilsithe. Ní suiteálaithe aipe iad comhaid samhlacha ná cartlanna foinse.",
    "platformDesktop": "Eagarthóireacht ar an deasc agus stóráil áitiúil.",
    "comingSoon": "Ag teacht go luath",
    "platformIos": "iPhone agus iPad",
    "platformTouch": "Roghnú agus eagarthóireacht don tadhall.",
    "releaseChecking": "Ag lorg íoslódálacha aipe foilsithe…",
    "installTitle": "InFlight a shuiteáil",
    "installIntro": "Níl leaganacha luatha sínithe ag Apple ná ag Microsoft fós, mar sin iarrfaidh gach córas ort deimhniú sula n-osclaítear é den chéad uair. Ná híoslódáil ach ón leathanach seo.",
    "installNote": "Ní athraítear agus ní uaslódáiltear do ghrianghraif riamh trí InFlight a shuiteáil nó a úsáid. Tiocfaidh suiteálaithe sínithe in áit na gcéimeanna seo in eisiúint níos déanaí.",
    "chooseTitle": "Roghnaigh conas tosú",
    "chooseFreeTitle": "Úsáid Basic saor in aisce, nó sínigh isteach",
    "chooseFreeBody": "Tá Basic saor in aisce go deo agus níl cuntas ag teastáil. Iompórtáil, roghnaigh, cuir in eagar agus easpórtáil ar do ghléas féin, as líne.",
    "chooseFreeGet": "Faigh Basic",
    "chooseSignIn": "An bhfuil cuntas agat cheana? Sínigh isteach ón aip InFlight. Cuirtear aon cheadúnas a cheannaigh tú leis an ngléas sin nuair a shíníonn tú isteach.",
    "chooseProTitle": "Liostáil le Pro",
    "promoBanner": "Tairiscint Aoine Dhubh: is saoire Pro nuair a shíníonn tú isteach agus a cheannaíonn tú faoi dheireadh {lastDay}. Taispeánann an tseiceáil amach an praghas laghdaithe sula n-íocann tú.",
    "chooseSubBody": "Íoc gach mí nó gach bliain agus cealaigh am ar bith. Má stopann tú, filleann do chuntas ar Basic, atá saor in aisce: ní chuirtear glas ar do thionscadail, d’eagarthóireachtaí ná d’easpórtálacha choíche.",
    "choosePricePromise": "Gealltanas praghais: ní ardóidh praghas do shíntiúis riamh gan fógra 30 lá ar a laghad trí ríomhphost, agus ní thosaíonn praghas nua ach ag athnuachan i ndiaidh an fhógra sin. Is féidir leat cealú roimhe sin.",
    "chooseBuyHow": "Chun liostáil, sínigh isteach ón aip InFlight agus roghnaigh Liostáil le Pro. Is é Paddle, ár n-athdhíoltóir, a ritheann an íocaíocht.",
    "chooseTeamTitle": "Foirne agus eagraíochtaí",
    "chooseTeamBody": "Gearrtar praghas Enterprise in aghaidh an tsuíocháin, le bille amháin do d’eagraíocht. Inis dúinn cé mhéad duine a bhfuil sé ag teastáil uathu agus seolfaimid meastachán.",
    "chooseTeamContact": "Déan teagmháil linn faoi Enterprise",
    "pricingTitle": "Praghsanna",
    "freeTitle": "Basic",
    "freePill": "Le linn tástála",
    "freeBody": "Iompórtáil, roghnaigh, cuir in eagar agus easpórtáil ar do ríomhaire féin, as líne.",
    "proTitle": "Pro",
    "priceTax": "Praghsanna na RA, CBL san áireamh. Taispeánann Paddle an praghas i d’airgeadra féin, le haon cháin do do thír, sula n-íocann tú.",
    "reqTitle": "Riachtanais chórais",
    "startTitle": "Tús a chur leis",
    "devicesTitle": "Do ghrianghraif, do stóras, do ghléasanna",
    "privacyTitle": "Is leatsa do ghrianghraif i gcónaí",
    "privacyBody": "Is áitiúil ar dtús é InFlight. Iompórtáil, roghnaigh agus cuir in eagar gan chuntas. Ní mór anailís roghnach ar líne nó gnéithe néil amach anseo a chasadh air d’aon ghnó. Ní uaslódáiltear do bhunchomhaid i ngan fhios duit.",
    "contactTitle": "Déan teagmháil le InFlight",
    "contactName": "Ainm",
    "contactEmail": "Ríomhphost",
    "contactMessage": "Teachtaireacht",
    "contactConsent": "Is féidir le InFlight mo ríomhphost agus mo theachtaireacht a stóráil chun freagra a thabhairt.",
    "contactSend": "Seol teachtaireacht",
    "footerText": "InFlight · Réamheisiúint",
    "footerReport": "Tuairiscigh fadhb",
    "demoDisclaimer": "<strong>Taispeántas de na huirlisí é seo, ní an aip iomlán.</strong> Úsáideann sé íomhánna samplacha beaga agus réamhamharc simplithe, ní inneall RAW InFlight. Taispeántar laghdú torainn agus roghnú ábhair le leaganacha réamhdhéanta de gach sampla.",
    "installMac": "Oscail an íomhá diosca a íoslódáladh agus tarraing InFlight go Applications. An chéad uair, deaschliceáil InFlight, roghnaigh <strong>Open</strong>, ansin <strong>Open</strong> arís.",
    "installWindows": "Rith an suiteálaí. Má deir Windows gur chosain sé do PC, roghnaigh <strong>More info</strong>, ansin <strong>Run anyway</strong>.",
    "pricingIntro": "<strong>Tá Basic saor in aisce go deo.</strong> Is síntiús é Pro, íoctha gach mí nó gach bliain. Liostálann tú ón aip InFlight; ní ghlacann an suíomh seo féin le híocaíochtaí.",
    "reqMac": "<strong>macOS:</strong> le deimhniú nuair a bheidh an chéad leagan tástáilte ar Macs fíora (tógtha do Apple silicon agus Intel).",
    "reqWindows": "<strong>Windows:</strong> le deimhniú nuair a bheidh an chéad leagan tástáilte ar PCs fíora.",
    "reqStorage": "<strong>Stóras:</strong> spás don mhúnla speiceas roghnach ar an ngléas (thart ar 90 MB) agus do chatalóg. Is féidir le bunchomhaid fanacht ar thiomántáin sheachtracha.",
    "startImport": "<strong>Iompórtáil:</strong> roghnaigh grianghraif nó fillteán atá ar do ghléas. Coinnigh cúltaca ar leith de do bhunchomhaid.",
    "startCull": "<strong>Roghnaigh:</strong> athbhreithnigh grianghraif, marcáil Coinnigh nó Diúltaigh, agus cuir frámaí in aice a chéile i gcomparáid.",
    "startEdit": "<strong>Cuir in eagar:</strong> coigeartaigh an solas, an dath agus an bearradh. Is féidir eagarthóireacht a chealú agus ní athscríobhann sí an bunchomhad.",
    "startExport": "<strong>Easpórtáil:</strong> roghnaigh formáid agus sábháil an grianghraf críochnaithe.",
    "nikonNote": "<strong>Nóta faoi RAW Nikon:</strong> Faoi láthair braitheann láimhseáil NEF sa bhrabhsálaí ar réamhamhairc atá istigh sa chomhad. Ní mór díchódú RAW lánréitigh, lena n-áirítear leaganacha High Efficiency Nikon, a bhailíochtú i leaganacha dúchasacha sula bhfógrófar go dtacaítear leis.",
    "devicesAnywhere": "<strong>Coinnigh grianghraif áit ar bith:</strong> ar aon tiomántán, NAS, nó fillteán a shioncronaíonn iCloud Drive, Dropbox nó OneDrive. Ní bhogann agus ní athraíonn InFlight do bhunchomhaid riamh.",
    "devicesCopy": "<strong>Cóipeáil socruithe chuig gléas eile:</strong> roghnaigh <em>Sábháil comhad socruithe</em> agus sábháil in iCloud Drive é, ansin roghnaigh <em>Luchtaigh comhad socruithe</em> ar do Mhac, PC nó fón eile.",
