    "tour1Title": "Roghnaigh grianghraf samplach",
    "tour1Body": "Tosaíonn gach sampla dorcha, maol nó gráinneach, cosúil le comhad díreach ón gceamara. Roghnaigh ceann le cur in eagar.",
    "tour2Title": "Solas",
    "tour2Body": "Nochtadh, codarsnacht, buaicphointí, scáthanna, bána agus dubha. Tarraing sleamhnán nó úsáid na saigheadeochracha. Roghnaigh an uimhir chun é a athshocrú.",
    "tour3Title": "Dath",
    "tour3Body": "Ceartaíonn teocht agus imir dathanna míchearta. Ardaíonn beogacht dathanna maola ar dtús; athraíonn sáithiú gach ceann acu.",
    "tour4Title": "Mionsonraí agus laghdú torainn",
    "tour4Body": "Cuireann soiléire codarsnacht áitiúil leis. Is taispeántas é laghdú torainn anseo a aistríonn chuig íomhá níos glaine réamhdhéanta, ní dí-thoránaí InFlight.",
    "tour5Title": "Masc",
    "tour5Body": "Roghnaigh an t-ábhar, ansin cuir an t-ábhar amháin nó an cúlra amháin in eagar. Tá an masc réamhdhéanta do gach sampla chun a thaispeáint conas a oibríonn roghnú ábhair.",
    "tour6Title": "Bearr agus dírigh",
    "tour6Body": "Roghnaigh cruth agus déan an léaslíne cothrom.",
    "tour7Title": "Roimh agus tar éis",
    "tour7Body": "Cas an scoilt air agus tarraing an roinnteoir, nó coinnigh “Taispeáin an bunleagan” brúite. Is oideas é d’eagarthóireacht, mar sin ní athraítear an bunleagan riamh.",
