    "matrixRowSpecies": "Moltaí speiceas ó mhúnla roghnach ar an ngléas",
    "matrixRowAssist": "Cabhair le grianghraif a roghnú: molann sé an ceann is fearr as gach sraith grianghraf",
    "matrixRowOnline": "Cúntóir ar líne roghnach, á úsáid ach amháin nuair a roghnaíonn tú é",
    "matrixNote": "Ní théann Basic in éag choíche agus níl cuntas ag teastáil uaidh. Is síntiús é Pro; má thagann deireadh leis, filleann an cuntas ar Basic. Ní choinnítear siar iompórtáil, eagarthóireacht ná easpórtáil choíche, ní chuirtear glas ar aon rud a rinne tú choíche, agus ní athraítear do bhunchóipeanna in eagrán ar bith.",
    "proBody": "Cuireann Pro moltaí speiceas, cabhair le grianghraif a roghnú agus an cúntóir ar líne roghnach leis. Oibríonn sé as líne: coinníonn gléas nach féidir leis seiceáil Pro ar feadh suas le 30 lá óna sheiceáil dheireanach, agus suas le 14 lá tar éis dáta athnuachana.",
