    "vizHeroLabel": "Sceitse méadaithe d'eagarthóir InFlight. Tarraingíonn an pointeoir an sleamhnán Scáthanna, ansin Nochtadh, agus éiríonn an grianghraf níos gile. Taispeántar an t-athrú sa Stair, ansin tugann Cealaigh an dá chéim ar ais.",
    "vizExposure": "Nochtadh",
    "vizVibrance": "Beogacht",
    "vizOriginal": "Ní athraíonn an bhunchóip riamh",
    "vizImportLabel": "Tarraingíonn an pointeoir trí chomhad grianghraf isteach in InFlight. Ritheann barra dul chun cinn feadh an bharr agus iad á gcur leis, agus tagann na mionsamhlacha chun solais. Fanann na bunchomhaid san áit a bhfuil siad.",
    "vizDrop": "Scaoil grianghraif nó fillteán anseo",
    "vizAdded": "24 grianghraf curtha leis",
    "vizCullLabel": "Sé ghrianghraf i ngreille, roghnaithe ón méarchlár. Marcálann F an chéad cheann, tugann 4 ceithre réalta don dara ceann, diúltaíonn X don cheathrú ceann agus marcálann F an cúigiú ceann. Fanann an tríú grianghraf, ceann nach raibh InFlight cinnte faoi, marcáilte Le hathbhreithniú in ionad é a chaitheamh amach.",
    "vizRejected": "Diúltaithe",
    "vizEditLabel": "Ardaíonn an pointeoir Beogacht agus íslíonn sé Buaicphointí, agus athraíonn an grianghraf. Ansin brúitear Cealaigh faoi dhó, agus tá an grianghraf díreach mar a bhí.",
    "vizExportLabel": "Painéal easpórtála do 24 grianghraf, lánmhéid, mar JPEG. Brúnn an pointeoir Easpórtáil, líonann barra dul chun cinn, agus deir an painéal go bhfuil na 24 ar fad sábháilte.",
