    "vizFormat": "Formáid",
    "vizSize": "Méid",
    "vizSaved": "24 sábháilte",
    "vizModesLabel": "Trí mhód eitilte taobh le taobh: Aonair, Comhphíolóta agus Uathphíolóta. Roghnaíonn an pointeoir gach ceann ina sheal agus insíonn abairt shimplí thíos cad a dhéanann an mód sin.",
    "vizStar": "Réalta",
    "vizBrandLabel": "Trí ghrianghraf os cionn barra easpórtála leis an bhfoireann bhranda Do stiúideo. Brúnn an pointeoir Easpórtáil agus tuirlingíonn lógó le hainm an stiúideo ar gach grianghraf ina sheal.",
