    "rawAlso": "Osclaíonn sé comhaid RAW ó Samsung, Hasselblad, Phase One, Leica agus Leaf freisin. Tá siad seo nua, mar sin níl gach ceamara tástáilte fós.",
    "matrixCloudBasic": "Gan áireamh",
    "matrixCloudPro": "500 sa mhí",
    "matrixRowCloudRunner": "Eagarthóireacht sa scamall, agus tú sínithe isteach: ritheann roinnt céimeanna troma (inniu, laghdú torainn clasaiceach agus uasscálú) sa scamall, agus scriostar an chóip a seoladh tar éis gach rite",
