    "signIn": "Sínigh isteach",
    "heroHeadline": "Roghnaigh, cuir in eagar agus roinn seisiún. Fiú gan chomhartha.",
    "heroLeadNew": "Sórtálann InFlight seisiún, cuireann sé in eagar é agus easpórtálann sé é ag gach méid ar a bpostálann tú, agus ní bhaineann sé le do bhunchóipeanna riamh. Is féidir gach eagarthóireacht a chealú, agus oibríonn na haipeanna Mac agus Windows go hiomlán as líne, gan chuntas.",
    "welcomeTitle": "Fáilte go InFlight",
    "inviteOnly": "Trí chuireadh amháin fad atáimid ag tástáil.",
    "platformsNote": "Tá InFlight le haghaidh macOS, Windows, Linux, iOS agus Android, gan eagarthóir gréasáin. Níl íoslódáil ag ardán ach nuair a fheictear a chnaipe thíos; tá an chuid eile ag teacht go luath. Oibríonn sé as líne, gan chuntas.",
    "requestInvite": "Iarr cuireadh",
    "promiseLabel": "Na rudaí a gheallann InFlight",
    "promiseAiTitle": "Gan picteilíní ginte.",
    "promiseAiBody": "Ní chumann InFlight riamh agus ní chuireann sé aon rud in ionad a bhfuil i do ghrianghraf, agus ní scríobhann sé riamh ábhar ó shamhail i meiteashonraí do chomhad. Ní athraítear do bhunchóipeanna riamh. Tomhaiseann agus molann samhlacha (ábhar, fócas, speiceas, torann). Oibríonn laghdú torainn agus géarú ó phicteilíní do ghrianghraif féin; ní ghlanann an laghdú torainn foghlamtha roghnach ach na picteilíní atá ann cheana, agus ní úsáidtear é ach nuair a léiríonn seiceáil gur fhan na fíormhionsonraí. Is é Deisiú spotaí an t-aon eisceacht: cóipeálann sé ó áit eile i do ghrianghraf féin, agus ní dhéanann sé é ach san áit a gcuireann tú féin é.",
    "promiseYoursTitle": "Fanann do ghrianghraif leatsa.",
    "promiseYoursBody": "Ní athraítear ná ní bhogtar bunchóipeanna riamh, agus ní uaslódáiltear aon rud mura roghnaíonn tú é a roinnt.",
    "promiseSocialTitle": "Roinn ar na meáin shóisialta go héasca.",
    "promiseSocialBody": "Easpórtálann eagarthóireacht amháin gach barr agus méid a phostálann tú, réidh do gach ardán.",
    "promiseCollabTitle": "Cabhair sa scamall, nuair is mian leat.",
    "promiseCollabBody": "Seol grianghraif le haghaidh eagarthóireacht sa scamall nuair a theastaíonn cabhair ó do ghléas: 500 sa mhí ar Pro, 5,000 ar Pro Plus, ansin 0.3p an ceann ó Chreidmheas Scamaill. Scriostar an chóip a seoladh tar éis gach rite. Coinníonn Pro freisin 2.5 GB de ghrianghraif roghnaithe sa scamall, le hoscailt ar do ghléasanna eile.",
    "whyTitle": "Cén fáth a n-aistríonn grianghrafadóirí go InFlight",
    "why3Title": "An aip chéanna ar gach gléas",
    "why3Body": "Roinneann Mac, Windows agus Linux na scáileáin chéanna, agus tógfar na haipeanna iPhone, iPad agus Android, atá le teacht, ón gcód céanna, mar sin ní gá aon rud a fhoghlaim faoi dhó.",
    "why4Title": "Macánta faoi do ghrianghraif",
    "why4Body": "Gan picteilíní ginte agus gan sonraí cumtha. Nuair nach bhfuil sé cinnte faoi speiceas nó faoi dhath, deir sé é sin, i bhfocail, riamh le dath amháin.",
    "howTitle": "Conas a oibríonn sé",
    "how1Title": "1. Tabhair isteach do ghrianghraif",
    "how1Body": "Dírigh InFlight ar chárta nó ar fhillteán. Nascann sé le do bhunchóipeanna agus ní bhogann, ní athainmníonn ná ní athscríobhann sé iad riamh.",
    "how2Title": "2. Coinnigh na cinn is fearr, go réidh",
    "how2Body": "Marcáil, rátáil agus cuir i gcomparáid. Coinnítear grianghraif éiginnte le hathbhreithniú, gan iad a chaitheamh amach ar do shon riamh.",
    "how3Title": "3. Cuir in eagar, agus cealaigh aon rud",
    "how3Body": "Is oideas é gach athrú is féidir leat dul siar tríd. Oibríonn uirlisí ar an ngléas as líne, gan aon rud a uaslódáil.",
    "how4Title": "4. Easpórtáil agus roinn",
    "how4Body": "Easpórtálacha lánmhéide, réidh le priontáil, don ghréasán nó do na meáin shóisialta.",
    "shootTitle": "Déanta don seisiún freisin",
    "shootModesTitle": "Móid eitilte",
    "shootModesBody": "Roghnaigh an méid a dhéanann InFlight duit, tionscadal ar thionscadal. Ritheann sé ar do ghléas, agus ní athraíonn aon rud gan bealach soiléir ar ais.",
    "shootBrandTitle": "Do bhranda ar gach easpórtáil",
    "shootBrandBody": "Sábháil foireann bhranda uair amháin. Ansin cuireann Easpórtáil a lógó, a dathanna agus a stíl téacs ar gach grianghraf in aon chéim amháin. Fanann sé ar do ghléas.",
    "insideTitle": "Cad atá istigh",
    "inCullTitle": "Roghnú cliste",
    "inSubjectTitle": "Aithint ábhair",
    "inSubjectBody": "Ainmníonn sé speicis éan agus clibeálann sé aerárthaí agus feithiclí, ionas gur féidir leat seisiún a chuardach de réir a bhfuil ann. Nuair nach bhfuil sé cinnte, deir sé é sin.",
    "inSocialTitle": "Formáidí sóisialta",
    "inSocialBody": "Socraigh na bearrtha agus na méideanna a phostálann tú, uair amháin. Ansin easpórtálann eagarthóireacht amháin chuig gach formáid, gach ceann lena bhearradh féin.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Nótaí datha tomhaiste ón ngrianghraf féin, ní ó do scáileán, agus mínithe i bhfocail shimplí. Is féidir le grianghrafadóirí dathdhalla eagarthóireacht a dhéanamh go muiníneach.",
    "inMaskTitle": "Maisc, roimh agus tar éis, díthorannú",
    "inMaskBody": "Coigeartaigh cuid de ghrianghraf amháin, cuir roimh agus tar éis i gcomparáid, agus glan torann. Ní ghintear aon rud: gan picteilíní cumtha.",
    "inOverlayTitle": "Forleagain agus comharthaí uisce de do chuid féin",
    "inOverlayBody": "Sábháil do lógó, do dhathanna agus do stíl téacs mar fhoireann bhranda, agus cuireann Easpórtáil ar gach grianghraf iad in aon chéim amháin.",
    "whoTitle": "Cé dó é",
    "whoBody": "Aon duine: tosaitheoirí, gairmithe, nó le haghaidh spraoi. Tá gach uirlis ar an ngléas saor in aisce, gan teorainn.",
    "whoListLabel": "Déanta do",
    "whoLevels": "Tosaitheoirí agus gairmithe",
    "whoColour": "Grianghrafadóirí dathdhalla",
    "whoNeuro": "Grianghrafadóirí néarúil-éagsúla",
