    "basicOwn": "<strong>Íoslódáil é agus is leatsa é.</strong> Ní théann Basic in éag riamh agus níl cuntas ag teastáil",
    "basicOffline": "Iompórtáil, roghnaigh, cuir in eagar agus easpórtáil, go hiomlán as líne",
    "basicModels": "Gach samhail agus uirlis ar an ngléas, lena n-áirítear aithint speiceas agus roghnú cliste",
    "priceYear": "sa bhliain",
