    "plusStorage": "10 GB de stóráil scamaill, chun grianghraif roghnaithe a oscailt agus a chur in eagar ar do ghléasanna eile",
    "creditTitle": "Creidmheas Néil de réir úsáide",
    "creditBody": "Coinnigh níos mó grianghraf sa scamall do do ghléasanna eile, agus seol níos mó le haghaidh eagarthóireacht sa scamall. Ná híoc ach as an méid a úsáideann tú thar a bhfuil san áireamh. Cuir creidmheas leis ó £5, nó lig dó é a chur leis go huathoibríoch nuair a bhíonn d'iarmhéid íseal. Tugtar creidmheas ar aghaidh ó mhí go mí.",
