    "vizHintSolo": "Ní dhéanann InFlight faic go dtí go n-iarrann tú. Roghnaíonn agus cuireann tú in eagar thú féin.",
    "vizHintCopilot": "Molann cúntóir InFlight féin roghanna agus eagarthóireacht, mar shampla roghnú tar éis iompórtála. Faomhann tú gach ceann.",
    "vizHintAutopilot": "Cuireann InFlight i bhfeidhm na roghanna agus an eagarthóireacht a bhfuil sé cinnte fúthu. Fágtar aon rud éiginnte duit le hathbhreithniú.",
