    "languageLabel": "Langue",
    "heroTitle": "Plus de temps derrière l’appareil.",
    "heroLead": "InFlight est un espace de travail photo pour importer, trier, retoucher et exporter. Il vise à rendre la retouche plus rapide et plus facile à comprendre : trouvez vos meilleures photos, faites quelques retouches claires, puis exportez.",
    "heroDownloads": "Voir les téléchargements",
    "heroPricing": "Voir les tarifs",
    "aimsTitle": "Ce qu’InFlight cherche à faire",
    "aimOfflineTitle": "Travailler hors ligne",
    "aimOfflineBody": "Importez, triez, retouchez et exportez sans connexion internet ni compte. Vos photos restent sur votre appareil ou dans le stockage de votre choix.",
    "aimOriginalsTitle": "Ne jamais modifier vos originaux",
    "aimOriginalsBody": "InFlight ne modifie, ne déplace et ne remplace jamais un fichier original. Les retouches sont enregistrées comme des étapes que vous pouvez modifier ou annuler à tout moment.",
    "aimCalmTitle": "Rester calme et accessible",
    "aimCalmBody": "Un écran sobre, des mots simples, un accès complet au clavier et des animations réduites. Rien ne repose sur la couleur seule. Il est conçu en pensant aux photographes daltoniens, TDAH et autistes.",
    "aimHonestTitle": "Être honnête sur ce qu’il sait",
    "aimHonestBody": "Quand InFlight n’est pas sûr, il le dit. Il vous indique quand il affiche l’aperçu intégré d’un fichier RAW, n’invente jamais de détails et garde les photos incertaines pour que vous les examiniez, au lieu de les rejeter.",
    "aimHelpTitle": "Aider sans prendre le contrôle",
    "aimHelpBody": "L’apprentissage automatique peut aider à réduire le bruit, trouver un sujet ou suggérer un masque. Chaque suggestion reste à vous de vérifier et d’ajuster.",
    "aimSameTitle": "Fonctionner partout de la même façon",
    "aimSameBody": "Les mêmes outils et la même façon de travailler sous macOS, Windows et Linux, avec iPhone, iPad et Android à suivre.",
    "aimOnceTitle": "Sans engagement",
    "aimOnceBody": "Basic reste gratuit pour toujours. Pro est un abonnement résiliable à tout moment, et rien de ce que vous avez créé n’est bloqué si vous arrêtez. Les testeurs invités peuvent recevoir Pro gratuitement.",
