    "demoCredit": "Les photos d’exemple sont dessinées par ordinateur pour cette démo. Appuyez sur Échap pour fermer la visite.",
    "downloadsTitle": "Obtenir InFlight",
    "downloadsIntro": "InFlight est en développement. Les programmes d’installation n’apparaissent ici qu’après la publication d’une version correspondante de l’application. Les fichiers de modèles et les archives de sources ne sont pas des programmes d’installation.",
    "platformDesktop": "Retouche sur ordinateur et stockage local.",
