    "installIntro": "Les premières versions ne sont pas encore signées par Apple ou Microsoft : chaque système vous demande donc de confirmer avant le premier lancement. Téléchargez uniquement depuis cette page.",
    "installNote": "Installer ou utiliser InFlight ne modifie et n’envoie jamais vos photos. Des programmes d’installation signés remplaceront ces étapes dans une version ultérieure.",
    "chooseTitle": "Choisissez comment commencer",
    "chooseFreeTitle": "Utilisez Basic gratuitement, ou connectez-vous",
    "chooseFreeBody": "Basic est gratuit pour toujours et ne demande aucun compte. Importez, triez, retouchez et exportez sur votre propre appareil, hors ligne.",
    "chooseFreeGet": "Obtenir Basic",
    "chooseSignIn": "Vous avez déjà un compte ? Connectez-vous depuis l’app InFlight. Toute licence achetée est ajoutée à cet appareil lors de la connexion.",
    "chooseProTitle": "S’abonner à Pro",
    "promoBanner": "Offre Black Friday : Pro coûte moins cher si vous vous connectez et achetez avant la fin du {lastDay}. Le paiement affiche le prix réduit avant que vous payiez.",
    "chooseSubBody": "Payez au mois ou à l’année et résiliez à tout moment. Si vous arrêtez, votre compte repasse à Basic, qui est gratuit : vos projets, retouches et exports ne sont jamais bloqués.",
    "choosePricePromise": "Promesse de prix : le prix de votre abonnement n’augmente jamais sans au moins 30 jours de préavis par e-mail, et un nouveau prix ne s’applique qu’à un renouvellement après ce préavis. Vous pouvez résilier avant.",
    "chooseBuyHow": "Pour vous abonner, connectez-vous dans l’application InFlight et choisissez S’abonner à Pro. Paddle, notre revendeur, gère le paiement.",
    "chooseTeamTitle": "Équipes et organisations",
    "chooseTeamBody": "Enterprise est facturé par poste, avec une seule facture pour votre organisation. Dites-nous combien de personnes en ont besoin et nous vous enverrons un devis.",
