    "startTitle": "Premiers pas",
    "devicesTitle": "Vos photos, votre stockage, vos appareils",
    "privacyTitle": "Vos photos restent les vôtres",
    "privacyBody": "InFlight fonctionne d’abord en local. Importez, triez et retouchez sans compte. L’analyse en ligne facultative ou de futures fonctions cloud doivent être activées volontairement. Vos originaux ne sont jamais envoyés à votre insu.",
    "contactTitle": "Contacter InFlight",
    "contactName": "Nom",
    "contactEmail": "E-mail",
    "contactMessage": "Message",
    "contactConsent": "InFlight peut conserver mon e-mail et mon message pour me répondre.",
    "contactSend": "Envoyer le message",
    "footerText": "InFlight · Préversion",
    "footerReport": "Signaler un problème",
    "demoDisclaimer": "<strong>Ceci est une démo des outils, pas l’application complète.</strong> Elle utilise de petites images d’exemple et un aperçu simplifié, pas le moteur RAW d’InFlight. La réduction du bruit et la sélection du sujet sont montrées avec des versions préparées à l’avance de chaque exemple.",
    "installMac": "Ouvrez l’image disque téléchargée et faites glisser InFlight dans Applications. La première fois, faites un clic droit sur InFlight, choisissez <strong>Ouvrir</strong>, puis à nouveau <strong>Ouvrir</strong>.",
    "installWindows": "Lancez le programme d’installation. Si Windows indique avoir protégé votre ordinateur, choisissez <strong>Informations complémentaires</strong>, puis <strong>Exécuter quand même</strong>.",
    "pricingIntro": "<strong>Basic est gratuit pour toujours.</strong> Pro est un abonnement, payé au mois ou à l’année. Vous vous abonnez depuis l’application InFlight ; ce site ne prend pas de paiements lui-même.",
    "reqMac": "<strong>macOS :</strong> à confirmer une fois la première version testée sur de vrais Mac (conçue pour Apple silicon et Intel).",
    "reqWindows": "<strong>Windows :</strong> à confirmer une fois la première version testée sur de vrais PC.",
    "reqStorage": "<strong>Stockage :</strong> de la place pour le modèle d’espèces facultatif sur l’appareil (environ 90 Mo) et votre catalogue. Les originaux peuvent rester sur des disques externes.",
    "startImport": "<strong>Importer :</strong> choisissez des photos ou un dossier sur votre appareil. Gardez une sauvegarde séparée de vos originaux.",
    "startCull": "<strong>Trier :</strong> examinez les photos, marquez-les Garder ou Rejeter, et comparez les vues voisines.",
    "startEdit": "<strong>Retoucher :</strong> réglez la lumière, la couleur et le recadrage. Les retouches sont réversibles et ne réécrivent pas le fichier original.",
    "startExport": "<strong>Exporter :</strong> choisissez un format et enregistrez la photo rendue.",
    "nikonNote": "<strong>Note sur les RAW Nikon :</strong> dans le navigateur, les fichiers NEF reposent pour l’instant sur les aperçus intégrés. Le décodage RAW en pleine résolution, y compris les variantes Nikon High Efficiency, doit être validé dans les versions natives avant d’être annoncé comme pris en charge.",
    "devicesAnywhere": "<strong>Rangez vos photos où vous voulez :</strong> sur n’importe quel disque, un NAS ou un dossier synchronisé par iCloud Drive, Dropbox ou OneDrive. InFlight ne déplace ni ne modifie jamais vos originaux.",
    "devicesCopy": "<strong>Copier les réglages sur un autre appareil :</strong> choisissez <em>Enregistrer le fichier de réglages</em> et enregistrez-le dans iCloud Drive, puis choisissez <em>Charger le fichier de réglages</em> sur votre autre Mac, PC ou téléphone.",
