    "tour1Title": "Choisissez une photo d’exemple",
    "tour1Body": "Chaque exemple commence sombre, terne ou granuleux, comme un fichier sorti de l’appareil. Choisissez-en un à retoucher.",
    "tour2Title": "Lumière",
    "tour2Body": "Exposition, contraste, hautes lumières, ombres, blancs et noirs. Faites glisser un curseur ou utilisez les flèches. Sélectionnez la valeur pour la réinitialiser.",
    "tour3Title": "Couleur",
    "tour3Body": "La température et la teinte corrigent les dominantes. La vibrance renforce d’abord les couleurs ternes ; la saturation les modifie toutes.",
    "tour4Title": "Détail et bruit",
    "tour4Body": "La clarté ajoute du contraste local. Ici, la réduction du bruit est une démo qui passe à une image plus propre préparée à l’avance, pas le réducteur de bruit d’InFlight.",
    "tour5Title": "Masques",
