    "matrixNote": "Basic n’expire jamais et ne demande aucun compte. Pro est un abonnement ; s’il prend fin, le compte repasse à Basic. L’import, la retouche et l’export ne sont jamais limités, rien de ce que vous avez créé n’est jamais bloqué, et vos originaux ne sont jamais modifiés, quelle que soit l’édition.",
    "proBody": "Pro ajoute les suggestions d’espèces, l’aide au choix des photos et l’assistant en ligne facultatif. Il fonctionne hors ligne : un appareil qui ne peut pas vérifier garde Pro jusqu’à 30 jours après sa dernière vérification, et jusqu’à 14 jours après une date de renouvellement.",
