    "skipToContent": "Aller au contenu",
    "vizHeroLabel": "Un aperçu agrandi de l'éditeur InFlight. Le pointeur fait glisser le curseur Ombres, puis Exposition, et la photo s'éclaircit. La modification apparaît dans l'historique, puis Annuler revient sur les deux étapes.",
    "vizExposure": "Exposition",
