    "matrixCloudBasic": "Non inclus",
    "matrixCloudPro": "500 par mois",
    "matrixRowCloudRunner": "Retouches dans le cloud, une fois connecté : certaines étapes lourdes (aujourd'hui la réduction de bruit classique et l'agrandissement) se font dans le cloud, et la copie envoyée est supprimée après chaque traitement",
