    "navPlans": "Formules",
    "signIn": "Se connecter",
    "heroHeadline": "Triez, retouchez et partagez une séance. Même sans réseau.",
    "heroLeadNew": "InFlight trie un shooting, le retouche et l'exporte à chaque format où vous publiez, et ne touche jamais à vos originaux. Chaque retouche peut être annulée, et les applications Mac et Windows fonctionnent entièrement hors ligne, sans compte.",
    "welcomeTitle": "Bienvenue dans InFlight",
    "inviteOnly": "Sur invitation uniquement pendant les tests.",
    "platformsNote": "InFlight existe pour macOS, Windows, Linux, iOS et Android, sans éditeur web. Une plateforme n’a un téléchargement que lorsque son bouton apparaît ci-dessous ; les autres arrivent bientôt. Il fonctionne hors ligne, sans compte.",
    "requestInvite": "Demander une invitation",
    "promiseLabel": "Les engagements d'InFlight",
    "promiseAiTitle": "Aucun pixel généré.",
    "promiseAiBody": "InFlight n’invente et ne remplace jamais ce qui se trouve dans votre photo, et n’écrit jamais de contenu produit par un modèle dans les métadonnées de vos fichiers. Vos originaux ne sont jamais modifiés. Les modèles mesurent et suggèrent (sujet, mise au point, espèce, bruit). La réduction du bruit et la netteté partent des propres pixels de votre photo ; la réduction du bruit apprise, facultative, ne fait que nettoyer les pixels déjà présents, et ne sert que si un contrôle montre que les vrais détails sont restés. Seule exception : Correction des taches, qui copie depuis un autre endroit de votre propre photo, et seulement là où vous la placez vous-même.",
    "promiseYoursTitle": "Vos photos restent à vous.",
    "promiseYoursBody": "Les originaux ne sont jamais modifiés ni déplacés, et rien n'est envoyé en ligne sauf si vous choisissez de partager.",
    "promiseSocialTitle": "Partagez sur les réseaux en toute simplicité.",
    "promiseSocialBody": "Une seule retouche exporte tous les cadrages et formats que vous publiez, prêts pour chaque plateforme.",
    "promiseCollabTitle": "L’aide du cloud, quand vous le voulez.",
    "promiseCollabBody": "Envoyez des photos en retouche dans le cloud quand votre appareil a besoin d’un coup de main : 500 par mois avec Pro, 5 000 avec Pro Plus, puis 0,3 p chacune sur le crédit cloud. La copie envoyée est supprimée après chaque traitement. Pro garde aussi 2,5 Go de photos choisies dans le cloud, à ouvrir sur vos autres appareils.",
    "whyTitle": "Pourquoi les photographes passent à InFlight",
    "why3Title": "La même application sur chaque appareil",
    "why3Body": "Mac, Windows et Linux partagent les mêmes écrans, et les applications iPhone, iPad et Android, à venir, reposeront sur le même code : rien à réapprendre.",
    "why4Title": "Honnête sur vos photos",
    "why4Body": "Aucun pixel généré et aucun détail inventé. Quand il n'est pas sûr d'une espèce ou d'une couleur, il le dit, en mots, jamais par la seule couleur.",
    "howTitle": "Comment ça marche",
    "how1Title": "1. Importez vos photos",
    "how1Body": "Indiquez à InFlight une carte ou un dossier. Il crée un lien vers vos originaux et ne les déplace, ne les renomme et ne les réécrit jamais.",
    "how2Title": "2. Gardez les meilleures, sereinement",
    "how2Body": "Marquez, notez et comparez. Les photos incertaines sont gardées pour vérification, jamais jetées à votre place.",
    "how3Title": "3. Retouchez, et annulez tout",
    "how3Body": "Chaque modification est une recette que vous pouvez remonter. Les outils sur l'appareil fonctionnent hors ligne, sans rien envoyer.",
    "how4Title": "4. Exportez et partagez",
    "how4Body": "Exports en pleine taille, prêts pour l’impression, le web ou les réseaux sociaux.",
    "shootTitle": "Pensé aussi pour la séance",
    "shootModesTitle": "Modes de vol",
    "shootModesBody": "Choisissez ce qu'InFlight fait pour vous, projet par projet. Il fonctionne sur votre appareil, et rien ne change sans un retour en arrière simple.",
    "shootBrandTitle": "Votre marque sur chaque export",
    "shootBrandBody": "Enregistrez un kit de marque une fois. L'export pose ensuite son logo, ses couleurs et son style de texte sur chaque photo en une étape. Il reste sur votre appareil.",
    "insideTitle": "Ce qu'il contient",
    "inCullTitle": "Tri intelligent",
    "inSubjectTitle": "Identification du sujet",
    "inSubjectBody": "Nomme les espèces d'oiseaux et repère avions et véhicules, pour chercher une séance par son contenu. Quand il n'est pas sûr, il le dit.",
    "inSocialTitle": "Formats pour les réseaux",
    "inSocialBody": "Définissez une fois les cadrages et tailles que vous publiez. Une seule retouche s'exporte ensuite dans chaque format, chacun avec son cadrage.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Des notes de couleur mesurées sur la photo elle-même, pas sur votre écran, et expliquées en mots simples. Les photographes daltoniens retouchent en confiance.",
    "inMaskTitle": "Masques, avant/après, débruitage",
    "inMaskBody": "Retouchez une partie de la photo, comparez avant et après, et réduisez le bruit. Rien n'est généré : aucun pixel inventé.",
    "inOverlayTitle": "Incrustations et filigranes personnalisés",
    "inOverlayBody": "Enregistrez votre logo, vos couleurs et votre style de texte dans un kit de marque, et l'export les pose sur chaque photo en une étape.",
    "whoTitle": "Pour qui ?",
    "whoBody": "Tout le monde : débutants, pros, ou juste pour le plaisir. Tous les outils sur l’appareil sont gratuits, sans limite.",
