    "navPrivacy": "Datenschutz",
    "navContact": "Kontakt",
    "languageLabel": "Sprache",
    "heroTitle": "Mehr Zeit hinter der Kamera.",
    "heroLead": "InFlight ist ein Fotoarbeitsplatz zum Importieren, Aussortieren, Bearbeiten und Exportieren. Es soll das Bearbeiten schneller und verständlicher machen: Ihre besten Fotos finden, ein paar nachvollziehbare Anpassungen vornehmen und exportieren.",
    "heroDownloads": "Downloads ansehen",
    "heroPricing": "Preise ansehen",
    "aimsTitle": "Was InFlight erreichen will",
    "aimOfflineTitle": "Offline arbeiten",
    "aimOfflineBody": "Importieren, aussortieren, bearbeiten und exportieren Sie ohne Internetverbindung und ohne Konto. Ihre Fotos bleiben auf Ihrem Gerät oder in einem Speicher Ihrer Wahl.",
    "aimOriginalsTitle": "Originale nie verändern",
    "aimOriginalsBody": "InFlight verändert, verschiebt oder ersetzt keine Originaldatei. Bearbeitungen werden als Schritte gespeichert, die Sie jederzeit ändern oder rückgängig machen können.",
    "aimCalmTitle": "Ruhig und barrierearm",
    "aimCalmBody": "Eine ruhige Oberfläche, klare Worte, volle Tastaturbedienung und reduzierte Bewegung. Nichts hängt allein von Farbe ab. InFlight wird mit farbenblinden, autistischen Fotografen und Fotografen mit ADHS im Blick entwickelt.",
    "aimHonestTitle": "Ehrlich sagen, was es weiß",
    "aimHonestBody": "Wenn InFlight unsicher ist, sagt es das. Es zeigt an, wenn es die eingebettete Vorschau einer RAW-Datei verwendet, erfindet nie Details und behält unsichere Fotos zur Prüfung, statt sie auszusortieren.",
    "aimHelpTitle": "Helfen, ohne zu übernehmen",
    "aimHelpBody": "Maschinelles Lernen kann helfen, Rauschen zu reduzieren, ein Motiv zu finden oder eine Maske vorzuschlagen. Jeden Vorschlag prüfen und anpassen Sie selbst.",
    "aimSameTitle": "Überall gleich arbeiten",
    "aimSameBody": "Dieselben Werkzeuge und dieselbe Arbeitsweise unter macOS, Windows und Linux, iPhone, iPad und Android folgen.",
    "aimOnceTitle": "Keine Bindung",
    "aimOnceBody": "Basic bleibt dauerhaft kostenlos. Pro ist ein Abonnement, das Sie jederzeit kündigen können, und nichts, was Sie erstellt haben, wird gesperrt, wenn Sie aufhören. Eingeladene Testerinnen und Tester können Pro kostenlos erhalten.",
