    "tourFinish": "Fertig",
    "demoCredit": "Die Beispielfotos sind für diese Demo am Computer gezeichnet. Drücken Sie Esc, um die Tour zu schließen.",
    "downloadsTitle": "InFlight herunterladen",
    "downloadsIntro": "InFlight ist in Entwicklung. Installationsprogramme erscheinen hier erst, wenn eine passende App-Version veröffentlicht wurde. Modelldateien und Quellarchive sind keine Installationsprogramme.",
    "platformDesktop": "Bearbeitung am Computer und lokaler Speicher.",
