    "platformIos": "iPhone und iPad",
    "platformTouch": "Aussortieren und Bearbeiten für Touch.",
    "releaseChecking": "Veröffentlichte Downloads werden gesucht…",
    "installTitle": "InFlight installieren",
    "installIntro": "Frühe Versionen sind noch nicht von Apple oder Microsoft signiert, daher fragt jedes System vor dem ersten Start nach einer Bestätigung. Laden Sie nur von dieser Seite herunter.",
    "installNote": "Durch das Installieren oder Verwenden von InFlight werden Ihre Fotos nie verändert oder hochgeladen. Signierte Installationsprogramme ersetzen diese Schritte in einer späteren Version.",
    "chooseTitle": "Wählen Sie, wie Sie beginnen",
    "chooseFreeTitle": "Basic kostenlos nutzen oder anmelden",
    "chooseFreeBody": "Basic ist dauerhaft kostenlos und braucht kein Konto. Importieren, aussortieren, bearbeiten und exportieren auf Ihrem eigenen Gerät, offline.",
    "chooseFreeGet": "Basic holen",
    "chooseSignIn": "Schon ein Konto? Melden Sie sich in der InFlight-App an. Gekaufte Lizenzen werden diesem Gerät bei der Anmeldung hinzugefügt.",
    "chooseProTitle": "Pro abonnieren",
    "promoBanner": "Black-Friday-Angebot: Pro kostet weniger, wenn Sie sich bis Ende {lastDay} anmelden und kaufen. Der Bezahlvorgang zeigt den reduzierten Preis, bevor Sie zahlen.",
    "chooseSubBody": "Monatlich oder jährlich zahlen und jederzeit kündigen. Wenn Sie aufhören, wird Ihr Konto wieder zu Basic, das kostenlos ist: Ihre Projekte, Bearbeitungen und Exporte werden nie gesperrt.",
    "choosePricePromise": "Preisversprechen: Ihr Abopreis steigt nie ohne mindestens 30 Tage Vorankündigung per E-Mail, und ein neuer Preis gilt erst ab einer Verlängerung nach dieser Ankündigung. Sie können vorher kündigen.",
    "chooseBuyHow": "Melden Sie sich zum Abonnieren in der InFlight-App an und wählen Sie Pro abonnieren. Paddle, unser Wiederverkäufer, wickelt die Zahlung ab.",
    "chooseTeamTitle": "Teams und Organisationen",
    "chooseTeamBody": "Enterprise wird pro Platz berechnet, mit einer Rechnung für Ihre Organisation. Sagen Sie uns, wie viele Personen es brauchen, und wir senden ein Angebot.",
    "chooseTeamContact": "Kontakt wegen Enterprise",
    "pricingTitle": "Preise",
    "freeTitle": "Basic",
    "freePill": "Während der Tests",
    "freeBody": "Importieren, aussortieren, bearbeiten und exportieren Sie offline auf Ihrem eigenen Computer.",
    "proTitle": "Pro",
    "priceTax": "Preise im Vereinigten Königreich, inklusive Mehrwertsteuer. Paddle zeigt den Preis vor der Zahlung in Ihrer Währung und mit den Steuern Ihres Landes an.",
    "reqTitle": "Systemanforderungen",
    "startTitle": "Erste Schritte",
    "devicesTitle": "Ihre Fotos, Ihr Speicher, Ihre Geräte",
    "privacyTitle": "Ihre Fotos bleiben Ihre",
    "privacyBody": "InFlight arbeitet lokal. Importieren, aussortieren und bearbeiten Sie ohne Konto. Optionale Online-Analysen oder künftige Cloud-Funktionen müssen bewusst eingeschaltet werden. Ihre Originale werden nicht unbemerkt hochgeladen.",
    "contactTitle": "InFlight kontaktieren",
    "contactName": "Name",
    "contactEmail": "E-Mail",
    "contactMessage": "Nachricht",
    "contactConsent": "InFlight darf meine E-Mail-Adresse und Nachricht speichern, um zu antworten.",
    "contactSend": "Nachricht senden",
    "footerText": "InFlight · Vorabversion",
    "footerReport": "Problem melden",
    "demoDisclaimer": "<strong>Dies ist eine Demo der Werkzeuge, nicht die vollständige App.</strong> Sie verwendet kleine Beispielbilder und eine vereinfachte Vorschau, nicht die RAW-Engine von InFlight. Rauschreduzierung und Motivauswahl werden mit vorab erstellten Versionen jedes Beispiels gezeigt.",
    "installMac": "Öffnen Sie das heruntergeladene Festplattenabbild und ziehen Sie InFlight in „Programme“. Klicken Sie beim ersten Mal mit der rechten Maustaste auf InFlight, wählen Sie <strong>Öffnen</strong> und dann erneut <strong>Öffnen</strong>.",
    "installWindows": "Führen Sie das Installationsprogramm aus. Meldet Windows, dass der Computer geschützt wurde, wählen Sie <strong>Weitere Informationen</strong> und dann <strong>Trotzdem ausführen</strong>.",
    "pricingIntro": "<strong>Basic ist dauerhaft kostenlos.</strong> Pro ist ein Abonnement, monatlich oder jährlich bezahlt. Sie abonnieren in der InFlight-App; diese Website nimmt selbst keine Zahlungen an.",
    "reqMac": "<strong>macOS:</strong> wird bestätigt, sobald die erste Version auf echten Macs getestet ist (für Apple silicon und Intel erstellt).",
    "reqWindows": "<strong>Windows:</strong> wird bestätigt, sobald die erste Version auf echten PCs getestet ist.",
    "reqStorage": "<strong>Speicher:</strong> Platz für das optionale Artenmodell auf dem Gerät (etwa 90 MB) und Ihren Katalog. Originale können auf externen Laufwerken bleiben.",
    "startImport": "<strong>Importieren:</strong> Wählen Sie Fotos oder einen Ordner auf Ihrem Gerät. Bewahren Sie eine separate Sicherung Ihrer Originale auf.",
    "startCull": "<strong>Aussortieren:</strong> Sehen Sie Fotos durch, markieren Sie sie mit Behalten oder Ablehnen und vergleichen Sie benachbarte Aufnahmen.",
    "startEdit": "<strong>Bearbeiten:</strong> Passen Sie Licht, Farbe und Zuschnitt an. Bearbeitungen sind umkehrbar und überschreiben die Originaldatei nicht.",
    "startExport": "<strong>Exportieren:</strong> Wählen Sie ein Format und speichern Sie das gerenderte Foto.",
    "nikonNote": "<strong>Hinweis zu Nikon-RAW:</strong> Im Browser stützt sich die Verarbeitung von NEF-Dateien derzeit auf eingebettete Vorschauen. Die RAW-Dekodierung in voller Auflösung, einschließlich der Varianten Nikon High Efficiency, muss in nativen Versionen geprüft werden, bevor sie als unterstützt beworben wird.",
    "devicesAnywhere": "<strong>Fotos überall aufbewahren:</strong> auf jedem Laufwerk, einem NAS oder in einem Ordner, den iCloud Drive, Dropbox oder OneDrive synchronisiert. InFlight verschiebt oder verändert Ihre Originale nie.",
    "devicesCopy": "<strong>Einstellungen auf ein anderes Gerät kopieren:</strong> Wählen Sie <em>Einstellungsdatei speichern</em> und speichern Sie sie in iCloud Drive, dann wählen Sie <em>Einstellungsdatei laden</em> auf Ihrem anderen Mac, PC oder Telefon.",
