    "tour2Title": "Licht",
    "tour2Body": "Belichtung, Kontrast, Lichter, Tiefen, Weiß und Schwarz. Ziehen Sie einen Regler oder nutzen Sie die Pfeiltasten. Wählen Sie die Zahl, um sie zurückzusetzen.",
    "tour3Title": "Farbe",
