    "matrixNote": "Basic läuft nie ab und braucht kein Konto. Pro ist ein Abonnement; endet es, wird das Konto wieder zu Basic. Importieren, Bearbeiten und Exportieren werden nie eingeschränkt, nichts, was Sie erstellt haben, wird je gesperrt, und Ihre Originale werden in keiner Ausgabe verändert.",
    "proBody": "Pro bietet Artvorschläge, Hilfe bei der Fotoauswahl und den optionalen Online-Helfer. Es funktioniert offline: Ein Gerät, das nicht prüfen kann, behält Pro bis zu 30 Tage nach der letzten Prüfung und bis zu 14 Tage über ein Verlängerungsdatum hinaus.",
