    "priceMonthly": "pro Monat",
    "priceAnnual": "pro Jahr",
    "skipToContent": "Zum Inhalt springen",
    "vizHeroLabel": "Eine vergrößerte Skizze des InFlight-Editors. Der Zeiger zieht den Regler Schatten, dann Belichtung, und das Foto wird heller. Die Änderung erscheint im Verlauf, dann nimmt Rückgängig beide Schritte zurück.",
    "vizExposure": "Belichtung",
    "vizVibrance": "Dynamik",
    "vizOriginal": "Das Original bleibt immer unverändert",
    "vizImportLabel": "Der Zeiger zieht drei Fotodateien auf InFlight. Oben läuft ein Fortschrittsbalken, während sie hinzugefügt werden, und die Vorschaubilder erscheinen. Die Originaldateien bleiben, wo sie sind.",
    "vizDrop": "Fotos oder einen Ordner hier ablegen",
    "vizAdded": "24 Fotos hinzugefügt",
    "vizCullLabel": "Sechs Fotos im Raster, per Tastatur aussortiert. F markiert das erste, 4 gibt dem zweiten vier Sterne, X lehnt das vierte ab und F markiert das fünfte. Das dritte Foto, bei dem InFlight unsicher war, bleibt als Zu prüfen markiert, statt verworfen zu werden.",
    "vizRejected": "Abgelehnt",
    "vizEditLabel": "Der Zeiger zieht Dynamik hoch und Lichter herunter, und das Foto verändert sich. Dann wird zweimal Rückgängig gedrückt, und das Foto ist wieder genau wie vorher.",
    "vizExportLabel": "Ein Exportfenster für 24 Fotos in voller Größe als JPEG. Der Zeiger drückt Exportieren, ein Fortschrittsbalken füllt sich, und das Fenster meldet, dass alle 24 gespeichert sind.",
    "vizExportTitle": "24 Fotos exportieren",
    "vizFormat": "Format",
    "vizSize": "Größe",
    "vizSaved": "24 gespeichert",
    "vizModesLabel": "Drei Flugmodi nebeneinander: Solo, Co-Pilot und Autopilot. Der Zeiger wählt nacheinander jeden aus, und ein einfacher Satz darunter sagt, was der Modus tut.",
    "vizStar": "Stern",
    "vizBrandLabel": "Drei Fotos über einer Exportleiste mit dem Marken-Kit Ihr Studio. Der Zeiger drückt Exportieren, und ein Logo mit dem Studionamen landet nacheinander auf jedem Foto.",
    "vizYourStudio": "Ihr Studio",
    "vizBrandKit": "Marken-Kit",
    "rawFuji": "Fujifilm (die meisten Kameras)",
    "rawTitle": "Öffnet RAW-Dateien von",
    "rawListLabel": "Kamerahersteller, deren RAW-Dateien getestet sind",
    "rawAlso": "Öffnet auch RAW-Dateien von Samsung, Hasselblad, Phase One, Leica und Leaf. Diese sind neu, daher ist noch nicht jedes Modell getestet.",
    "matrixCloudBasic": "Nicht enthalten",
    "matrixCloudPro": "500 pro Monat",
    "matrixRowCloudRunner": "Cloud-Bearbeitung, angemeldet: Einige aufwendige Schritte (heute klassische Rauschminderung und Hochskalierung) laufen in der Cloud, und die gesendete Kopie wird nach jedem Durchlauf gelöscht",
    "matrixStoragePro": "2,5 GB",
    "matrixRowStorage": "Cloud-Speicher, um Ihre Fotos auf Ihren anderen Geräten zu öffnen",
    "navHow": "So funktioniert's",
    "navShoot": "Beim Shooting",
    "navPlans": "Tarife",
    "signIn": "Anmelden",
    "heroHeadline": "Ein Shooting aussortieren, bearbeiten und teilen. Auch ohne Netz.",
    "heroLeadNew": "InFlight sortiert ein Shooting, bearbeitet es und exportiert es in jeder Größe, in der Sie posten, und rührt Ihre Originale nie an. Jede Bearbeitung lässt sich rückgängig machen, und die Mac- und Windows-Apps funktionieren vollständig offline, ohne Konto.",
    "welcomeTitle": "Willkommen bei InFlight",
    "inviteOnly": "Während der Testphase nur auf Einladung.",
    "platformsNote": "InFlight ist für macOS, Windows, Linux, iOS und Android gedacht, einen Web-Editor gibt es nicht. Ein Download ist nur vorhanden, wenn unten die Schaltfläche erscheint; die übrigen Systeme folgen bald. Es funktioniert offline, ohne Konto.",
    "requestInvite": "Einladung anfragen",
    "promiseLabel": "Was InFlight verspricht",
    "promiseAiTitle": "Keine generierten Pixel.",
    "promiseAiBody": "InFlight erfindet oder ersetzt nie, was in Ihrem Foto ist, und schreibt nie von Modellen erzeugte Inhalte in die Metadaten Ihrer Dateien. Ihre Originale werden nie verändert. Modelle messen und schlagen vor (Motiv, Schärfe, Art, Rauschen). Rauschreduzierung und Schärfen arbeiten mit den eigenen Pixeln Ihres Fotos; die optionale gelernte Rauschreduzierung reinigt nur die vorhandenen Pixel und wird nur genutzt, wenn eine Prüfung zeigt, dass echte Details erhalten bleiben. Die einzige Ausnahme ist die Bereichsreparatur: Sie kopiert aus einer anderen Stelle Ihres eigenen Fotos, und nur dort, wo Sie sie selbst setzen.",
    "promiseYoursTitle": "Ihre Fotos bleiben Ihre.",
    "promiseYoursBody": "Originale werden nie verändert oder verschoben, und nichts wird hochgeladen, außer Sie entscheiden sich zum Teilen.",
    "promiseSocialTitle": "Einfach in sozialen Netzwerken teilen.",
    "promiseSocialBody": "Eine Bearbeitung exportiert jeden Ausschnitt und jede Größe, die Sie posten, passend für jede Plattform.",
    "promiseCollabTitle": "Hilfe aus der Cloud, wenn Sie sie wollen.",
    "promiseCollabBody": "Senden Sie Fotos zur Cloud-Bearbeitung, wenn Ihr Gerät Hilfe braucht: 500 im Monat mit Pro, 5.000 mit Pro Plus, danach je 0,3 p aus dem Cloud-Guthaben. Die gesendete Kopie wird nach jedem Durchlauf gelöscht. Pro hält außerdem 2,5 GB ausgewählter Fotos in der Cloud, zum Öffnen auf Ihren anderen Geräten.",
    "whyTitle": "Warum Fotografen zu InFlight wechseln",
    "why3Title": "Dieselbe App auf jedem Gerät",
    "why3Body": "Mac, Windows und Linux teilen dieselben Bildschirme, und die Apps für iPhone, iPad und Android, die noch kommen, werden aus demselben Code entstehen, also müssen Sie nichts zweimal lernen.",
    "why4Title": "Ehrlich zu Ihren Fotos",
    "why4Body": "Keine generierten Pixel und keine erfundenen Details. Ist es sich bei einer Art oder einer Farbe unsicher, sagt es das, in Worten, nie nur über Farbe.",
    "howTitle": "So funktioniert's",
    "how1Title": "1. Fotos hereinholen",
    "how1Body": "Zeigen Sie InFlight eine Karte oder einen Ordner. Es verknüpft Ihre Originale und verschiebt, benennt oder überschreibt sie nie.",
    "how2Title": "2. Die besten behalten, in Ruhe",
    "how2Body": "Markieren, bewerten und vergleichen. Unsichere Fotos werden zur Prüfung aufbewahrt, nie für Sie weggeworfen.",
    "how3Title": "3. Bearbeiten und alles rückgängig machen",
    "how3Body": "Jede Änderung ist ein Rezept, das Sie Schritt für Schritt zurückgehen können. Werkzeuge auf dem Gerät arbeiten offline, ohne Upload.",
    "how4Title": "4. Exportieren und teilen",
    "how4Body": "Exporte in voller Größe, bereit für Druck, Web oder soziale Medien.",
    "shootTitle": "Auch fürs Shooting gemacht",
    "shootModesTitle": "Flugmodi",
    "shootModesBody": "Wählen Sie, wie viel InFlight für Sie übernimmt, Projekt für Projekt. Es läuft auf Ihrem Gerät, und nichts ändert sich ohne einfachen Weg zurück.",
    "shootBrandTitle": "Ihre Marke auf jedem Export",
    "shootBrandBody": "Speichern Sie einmal ein Marken-Kit. Der Export setzt dann Logo, Farben und Textstil in einem Schritt auf jedes Foto. Es bleibt auf Ihrem Gerät.",
    "insideTitle": "Was drin ist",
    "inCullTitle": "Intelligentes Aussortieren",
    "inSubjectTitle": "Motiverkennung",
    "inSubjectBody": "Benennt Vogelarten und erkennt Flugzeuge und Fahrzeuge, damit Sie ein Shooting nach Inhalt durchsuchen können. Ist es unsicher, sagt es das.",
    "inSocialTitle": "Formate für soziale Netzwerke",
    "inSocialBody": "Legen Sie einmal die Ausschnitte und Größen fest, die Sie posten. Eine Bearbeitung exportiert dann in jedes Format, jedes mit eigenem Ausschnitt.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Farbhinweise, gemessen am Foto selbst, nicht an Ihrem Bildschirm, und in klaren Worten erklärt. Farbenblinde Fotografen bearbeiten mit Zuversicht.",
    "inMaskTitle": "Masken, Vorher/Nachher, Entrauschen",
    "inMaskBody": "Bearbeiten Sie nur einen Teil eines Fotos, vergleichen Sie vorher und nachher und reduzieren Sie Rauschen. Nichts wird generiert: keine erfundenen Pixel.",
    "inOverlayTitle": "Eigene Overlays und Wasserzeichen",
    "inOverlayBody": "Speichern Sie Logo, Farben und Textstil als Marken-Kit, und der Export setzt sie in einem Schritt auf jedes Foto.",
    "whoTitle": "Für wen?",
    "whoBody": "Alle: Einsteiger, Profis oder einfach zum Spaß. Jedes Werkzeug auf dem Gerät ist kostenlos und unbegrenzt.",
