    "languageLabel": "Idioma",
    "heroTitle": "Más tiempo detrás de la cámara.",
    "heroLead": "InFlight es un espacio de trabajo fotográfico para importar, seleccionar, editar y exportar. Busca que editar sea más rápido y más fácil de entender: encuentre sus mejores fotos, haga unos pocos ajustes que pueda seguir y exporte.",
    "heroDownloads": "Ver descargas",
    "heroPricing": "Ver precios",
    "aimsTitle": "Lo que InFlight se propone",
    "aimOfflineTitle": "Trabajar sin conexión",
    "aimOfflineBody": "Importe, seleccione, edite y exporte sin conexión a internet y sin cuenta. Sus fotos se quedan en su dispositivo o en el almacenamiento que elija.",
    "aimOriginalsTitle": "No cambiar nunca sus originales",
    "aimOriginalsBody": "InFlight no cambia, mueve ni sustituye ningún archivo original. Los cambios se guardan como pasos que puede modificar o deshacer en cualquier momento.",
    "aimCalmTitle": "Tranquilo y accesible",
    "aimCalmBody": "Una pantalla tranquila, palabras sencillas, acceso completo con el teclado y movimiento reducido. Nada depende solo del color. Está pensado para fotógrafos daltónicos, con TDAH o autistas.",
    "aimHonestTitle": "Ser sincero sobre lo que sabe",
    "aimHonestBody": "Cuando InFlight no está seguro, lo dice. Le avisa cuando muestra la vista previa integrada de un archivo RAW, nunca inventa detalles y conserva las fotos dudosas para que usted las revise, en lugar de rechazarlas.",
    "aimHelpTitle": "Ayudar sin tomar el control",
