    "privacyTitle": "Sus fotos siguen siendo suyas",
    "privacyBody": "InFlight trabaja primero en local. Importe, seleccione y edite sin cuenta. El análisis en línea opcional o las futuras funciones en la nube deben activarse a propósito. Sus originales no se suben sin que lo sepa.",
