    "footerText": "InFlight · Versión preliminar",
    "footerReport": "Informar de un problema",
    "demoDisclaimer": "<strong>Esto es una demo de las herramientas, no la aplicación completa.</strong> Usa imágenes de muestra pequeñas y una vista previa simplificada, no el motor RAW de InFlight. La reducción de ruido y la selección del sujeto se muestran con versiones de cada muestra preparadas de antemano.",
    "installMac": "Abra la imagen de disco descargada y arrastre InFlight a Aplicaciones. La primera vez, haga clic derecho en InFlight, elija <strong>Abrir</strong> y, después, <strong>Abrir</strong> de nuevo.",
    "installWindows": "Ejecute el instalador. Si Windows indica que ha protegido su PC, elija <strong>Más información</strong> y, después, <strong>Ejecutar de todas formas</strong>.",
    "pricingIntro": "<strong>Basic es gratis para siempre.</strong> Pro es una suscripción, pagada al mes o al año. Te suscribes desde la app InFlight; esta web no cobra pagos por sí misma.",
    "reqMac": "<strong>macOS:</strong> por confirmar cuando la primera versión se pruebe en Mac reales (creada para Apple silicon e Intel).",
    "reqWindows": "<strong>Windows:</strong> por confirmar cuando la primera versión se pruebe en PC reales.",
    "reqStorage": "<strong>Almacenamiento:</strong> espacio para el modelo opcional de especies en el dispositivo (unos 90 MB) y su catálogo. Los originales pueden quedarse en discos externos.",
    "startImport": "<strong>Importar:</strong> elija fotos o una carpeta guardada en su dispositivo. Mantenga una copia de seguridad aparte de sus originales.",
    "startCull": "<strong>Seleccionar:</strong> revise las fotos, márquelas como Conservar o Rechazar y compare tomas contiguas.",
    "startEdit": "<strong>Editar:</strong> ajuste la luz, el color y el recorte. Los cambios son reversibles y no reescriben el archivo original.",
    "startExport": "<strong>Exportar:</strong> elija un formato y guarde la foto procesada.",
    "nikonNote": "<strong>Nota sobre RAW de Nikon:</strong> en el navegador, los archivos NEF dependen por ahora de las vistas previas integradas. La decodificación RAW a resolución completa, incluidas las variantes Nikon High Efficiency, debe validarse en las versiones nativas antes de anunciarse como compatible.",
    "devicesAnywhere": "<strong>Guarde sus fotos donde quiera:</strong> en cualquier disco, un NAS o una carpeta sincronizada con iCloud Drive, Dropbox o OneDrive. InFlight nunca mueve ni cambia sus originales.",
    "devicesCopy": "<strong>Copiar los ajustes a otro dispositivo:</strong> elija <em>Guardar archivo de ajustes</em> y guárdelo en iCloud Drive; después, elija <em>Cargar archivo de ajustes</em> en su otro Mac, PC o teléfono.",
