    "heroHeadline": "Descarta, edita y comparte una sesión. Incluso sin cobertura.",
    "heroLeadNew": "InFlight ordena una sesión, la edita y la exporta en cada tamaño en que publicas, y nunca toca tus originales. Cada edición se puede deshacer, y las aplicaciones de Mac y Windows funcionan totalmente sin conexión, sin cuenta.",
    "welcomeTitle": "Te damos la bienvenida a InFlight",
    "inviteOnly": "Solo con invitación mientras hacemos pruebas.",
    "platformsNote": "InFlight es para macOS, Windows, Linux, iOS y Android, y no tiene editor web. Una plataforma solo tiene descarga cuando aparece su botón más abajo; las demás llegan pronto. Funciona sin conexión y sin cuenta.",
    "requestInvite": "Pedir una invitación",
    "promiseLabel": "Lo que promete InFlight",
    "promiseAiTitle": "Sin píxeles generados.",
    "promiseAiBody": "InFlight nunca inventa ni sustituye lo que hay en tu foto, y nunca escribe contenido hecho por un modelo en los metadatos de tus archivos. Tus originales nunca cambian. Los modelos miden y sugieren (sujeto, enfoque, especie, ruido). La reducción de ruido y el enfoque trabajan con los propios píxeles de tu foto; la reducción de ruido aprendida, opcional, solo limpia los píxeles que ya están, y solo se usa si una comprobación muestra que el detalle real se conserva. La única excepción es Corrección de manchas, que copia de otra parte de tu propia foto, y solo donde tú la colocas.",
    "promiseYoursTitle": "Tus fotos siguen siendo tuyas.",
    "promiseYoursBody": "Los originales nunca se modifican ni se mueven, y no se sube nada salvo que decidas compartir.",
    "promiseSocialTitle": "Comparte en redes sin esfuerzo.",
    "promiseSocialBody": "Una sola edición exporta cada recorte y tamaño que publicas, listo para cada plataforma.",
    "promiseCollabTitle": "Ayuda en la nube, cuando la quieras.",
    "promiseCollabBody": "Envía fotos para editarlas en la nube cuando tu dispositivo necesite una mano: 500 al mes con Pro, 5.000 con Pro Plus, y después 0,3 p cada una del crédito en la nube. La copia enviada se borra después de cada proceso. Pro también guarda 2,5 GB de fotos elegidas en la nube, para abrirlas en tus otros dispositivos.",
    "whyTitle": "Por qué los fotógrafos se pasan a InFlight",
    "why3Title": "La misma aplicación en cada dispositivo",
    "why3Body": "Mac, Windows y Linux comparten las mismas pantallas, y las apps de iPhone, iPad y Android, que están por llegar, se crearán con el mismo código, así que no hay que aprender nada dos veces.",
    "why4Title": "Honesto con tus fotos",
    "why4Body": "Sin píxeles generados ni detalles inventados. Cuando no está seguro de una especie o un color, lo dice, con palabras, nunca solo con color.",
    "howTitle": "Cómo funciona",
    "how1Title": "1. Trae tus fotos",
    "how1Body": "Indica a InFlight una tarjeta o una carpeta. Enlaza tus originales y nunca los mueve, renombra ni reescribe.",
    "how2Title": "2. Quédate con las mejores, con calma",
    "how2Body": "Marca, puntúa y compara. Las fotos dudosas se guardan para revisarlas, nunca se tiran por ti.",
    "how3Title": "3. Edita y deshaz lo que quieras",
    "how3Body": "Cada cambio es una receta que puedes recorrer hacia atrás. Las herramientas del dispositivo funcionan sin conexión, sin subir nada.",
    "how4Title": "4. Exporta y comparte",
    "how4Body": "Exportaciones a tamaño completo, listas para imprimir, la web o las redes sociales.",
    "shootTitle": "Hecho también para la sesión",
    "shootModesTitle": "Modos de vuelo",
    "shootModesBody": "Elige cuánto hace InFlight por ti, proyecto a proyecto. Funciona en tu dispositivo, y nada cambia sin una forma clara de volver atrás.",
    "shootBrandTitle": "Tu marca en cada exportación",
    "shootBrandBody": "Guarda un kit de marca una vez. Después, Exportar pone su logotipo, colores y estilo de texto en cada foto en un solo paso. Se queda en tu dispositivo.",
    "insideTitle": "Qué incluye",
    "inCullTitle": "Descarte inteligente",
    "inSubjectTitle": "Identificación del sujeto",
    "inSubjectBody": "Nombra especies de aves y etiqueta aviones y vehículos, para buscar en una sesión por lo que contiene. Cuando no está seguro, lo dice.",
    "inSocialTitle": "Formatos para redes",
    "inSocialBody": "Define una vez los recortes y tamaños que publicas. Después, una sola edición se exporta a cada formato, cada uno con su recorte.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Notas de color medidas en la propia foto, no en tu pantalla, y explicadas con palabras sencillas. Los fotógrafos daltónicos editan con confianza.",
    "inMaskTitle": "Máscaras, antes y después, reducción de ruido",
    "inMaskBody": "Ajusta solo una parte de la foto, compara antes y después, y limpia el ruido. No se genera nada: ningún píxel inventado.",
    "inOverlayTitle": "Superposiciones y marcas de agua propias",
