    "heroTitle": "Meer tijd achter de camera.",
    "heroLead": "InFlight is een fotowerkplek om te importeren, selecteren, bewerken en exporteren. Het wil bewerken sneller en begrijpelijker maken: vind uw beste foto’s, maak een paar bewerkingen die u kunt volgen en exporteer.",
    "heroDownloads": "Bekijk downloads",
    "heroPricing": "Bekijk prijzen",
    "aimsTitle": "Wat InFlight wil bereiken",
    "aimOfflineTitle": "Offline werken",
    "aimOfflineBody": "Importeer, selecteer, bewerk en exporteer zonder internetverbinding of account. Uw foto’s blijven op uw apparaat of in opslag die u zelf kiest.",
    "aimOriginalsTitle": "Uw originelen nooit wijzigen",
    "aimOriginalsBody": "InFlight wijzigt, verplaatst of vervangt nooit een origineel bestand. Bewerkingen worden bewaard als stappen die u altijd kunt aanpassen of ongedaan maken.",
    "aimCalmTitle": "Rustig en toegankelijk",
    "aimCalmBody": "Een rustig scherm, eenvoudige woorden, volledige toetsenbordtoegang en minder beweging. Niets hangt alleen van kleur af. Het is ontworpen met kleurenblinde en autistische fotografen en fotografen met ADHD in gedachten.",
    "aimHonestTitle": "Eerlijk over wat het weet",
    "aimHonestBody": "Als InFlight het niet zeker weet, zegt het dat. Het meldt wanneer het de ingebouwde voorvertoning van een RAW-bestand toont, verzint nooit details en bewaart twijfelachtige foto’s zodat u ze kunt beoordelen, in plaats van ze af te wijzen.",
    "aimHelpTitle": "Helpen zonder over te nemen",
    "aimHelpBody": "Machine learning kan helpen ruis te verminderen, een onderwerp te vinden of een masker voor te stellen. Elk voorstel controleert en past u zelf aan.",
    "aimSameTitle": "Overal hetzelfde werken",
    "aimSameBody": "Dezelfde hulpmiddelen en dezelfde manier van werken op macOS, Windows en Linux, met iPhone, iPad en Android in het vervolg.",
    "aimOnceTitle": "Nergens aan vast",
    "aimOnceBody": "Basic blijft altijd gratis. Pro is een abonnement dat je altijd kunt opzeggen, en niets wat je hebt gemaakt wordt vergrendeld als je stopt. Uitgenodigde testers kunnen Pro gratis krijgen.",
