    "downloadsTitle": "InFlight downloaden",
    "downloadsIntro": "InFlight is in ontwikkeling. Installatieprogramma’s verschijnen hier pas als een bijbehorende app-versie is gepubliceerd. Modelbestanden en bronarchieven zijn geen installatieprogramma’s.",
