    "releaseChecking": "Zoeken naar gepubliceerde downloads…",
    "installTitle": "InFlight installeren",
    "installIntro": "Vroege versies zijn nog niet ondertekend door Apple of Microsoft, dus elk systeem vraagt u om bevestiging vóór de eerste start. Download alleen via deze pagina.",
    "installNote": "Door InFlight te installeren of te gebruiken worden uw foto’s nooit gewijzigd of geüpload. Ondertekende installatieprogramma’s vervangen deze stappen in een latere versie.",
    "chooseTitle": "Kies hoe je begint",
    "chooseFreeTitle": "Gebruik Basic gratis, of log in",
    "chooseFreeBody": "Basic is voorgoed gratis en heeft geen account nodig. Importeren, schiften, bewerken en exporteren op je eigen apparaat, offline.",
    "chooseFreeGet": "Basic downloaden",
    "chooseSignIn": "Heb je al een account? Log in vanuit de InFlight-app. Licenties die je hebt gekocht worden bij het inloggen aan dat apparaat toegevoegd.",
    "chooseProTitle": "Abonneer op Pro",
    "promoBanner": "Black Friday-aanbieding: Pro kost minder als je inlogt en koopt vóór het einde van {lastDay}. De betaalpagina toont de verlaagde prijs voordat je betaalt.",
    "chooseSubBody": "Betaal per maand of per jaar en zeg op wanneer je wilt. Als je stopt, wordt je account weer Basic, dat gratis is: je projecten, bewerkingen en exports worden nooit vergrendeld.",
    "choosePricePromise": "Prijsbelofte: je abonnementsprijs gaat nooit omhoog zonder minstens 30 dagen vooraf bericht per e-mail, en een nieuwe prijs geldt pas vanaf een verlenging na dat bericht. Je kunt eerder opzeggen.",
    "chooseBuyHow": "Log om je te abonneren in via de InFlight-app en kies Abonneer op Pro. Paddle, onze wederverkoper, regelt de betaling.",
    "chooseTeamTitle": "Teams en organisaties",
    "chooseTeamBody": "Enterprise wordt per plek geprijsd, met één rekening voor je organisatie. Laat weten hoeveel mensen het nodig hebben en we sturen een offerte.",
    "chooseTeamContact": "Neem contact op over Enterprise",
    "pricingTitle": "Prijzen",
    "freeTitle": "Basic",
    "freePill": "Tijdens het testen",
    "freeBody": "Importeer, selecteer, bewerk en exporteer op uw eigen computer, offline.",
    "proTitle": "Pro",
    "priceTax": "Prijzen in het VK, inclusief btw. Paddle toont de prijs in jouw valuta, met de belasting van jouw land, voordat je betaalt.",
    "reqTitle": "Systeemvereisten",
    "startTitle": "Aan de slag",
    "devicesTitle": "Uw foto’s, uw opslag, uw apparaten",
    "privacyTitle": "Uw foto’s blijven van u",
    "privacyBody": "InFlight werkt in de eerste plaats lokaal. Importeer, selecteer en bewerk zonder account. Optionele online analyse of toekomstige cloudfuncties moet u bewust inschakelen. Uw originelen worden niet ongemerkt geüpload.",
    "contactTitle": "Contact met InFlight",
    "contactName": "Naam",
    "contactEmail": "E-mail",
    "contactMessage": "Bericht",
    "contactConsent": "InFlight mag mijn e-mailadres en bericht bewaren om te antwoorden.",
    "contactSend": "Bericht versturen",
    "footerText": "InFlight · Voorlopige versie",
    "footerReport": "Probleem melden",
    "demoDisclaimer": "<strong>Dit is een demo van de tools, niet de volledige app.</strong> Hij gebruikt kleine voorbeeldafbeeldingen en een vereenvoudigde voorvertoning, niet de RAW-engine van InFlight. Ruisonderdrukking en onderwerpselectie worden getoond met vooraf gemaakte versies van elk voorbeeld.",
    "installMac": "Open de gedownloade schijfkopie en sleep InFlight naar Apps. Klik de eerste keer met de rechtermuisknop op InFlight, kies <strong>Open</strong> en dan nogmaals <strong>Open</strong>.",
    "installWindows": "Start het installatieprogramma. Als Windows meldt dat uw pc is beschermd, kies dan <strong>Meer informatie</strong> en daarna <strong>Toch uitvoeren</strong>.",
    "pricingIntro": "<strong>Basic is altijd gratis.</strong> Pro is een abonnement, per maand of per jaar betaald. Je abonneert je in de InFlight-app; deze website neemt zelf geen betalingen aan.",
    "reqMac": "<strong>macOS:</strong> wordt bevestigd zodra de eerste versie op echte Macs is getest (gemaakt voor Apple silicon en Intel).",
    "reqWindows": "<strong>Windows:</strong> wordt bevestigd zodra de eerste versie op echte pc’s is getest.",
    "reqStorage": "<strong>Opslag:</strong> ruimte voor het optionele soortenmodel op het apparaat (ongeveer 90 MB) en uw catalogus. Originelen kunnen op externe schijven blijven.",
    "startImport": "<strong>Importeren:</strong> kies foto’s of een map op uw apparaat. Bewaar een aparte back-up van uw originelen.",
    "startCull": "<strong>Selecteren:</strong> bekijk foto’s, markeer ze als Bewaren of Afwijzen en vergelijk opeenvolgende opnamen.",
    "startEdit": "<strong>Bewerken:</strong> pas licht, kleur en uitsnede aan. Bewerkingen zijn omkeerbaar en overschrijven het originele bestand niet.",
    "startExport": "<strong>Exporteren:</strong> kies een formaat en sla de gerenderde foto op.",
    "nikonNote": "<strong>Opmerking over Nikon-RAW:</strong> in de browser zijn NEF-bestanden nu nog afhankelijk van ingebouwde voorvertoningen. RAW-decodering op volledige resolutie, ook van de Nikon High Efficiency-varianten, moet in native versies worden gevalideerd voordat het als ondersteund wordt aangekondigd.",
    "devicesAnywhere": "<strong>Bewaar foto’s waar u wilt:</strong> op elke schijf, een NAS of een map die iCloud Drive, Dropbox of OneDrive synchroniseert. InFlight verplaatst of wijzigt uw originelen nooit.",
    "devicesCopy": "<strong>Instellingen naar een ander apparaat kopiëren:</strong> kies <em>Instellingenbestand opslaan</em> en sla het op in iCloud Drive; kies daarna <em>Instellingenbestand laden</em> op uw andere Mac, pc of telefoon.",
