    "tour1Title": "Kies een voorbeeldfoto",
    "tour1Body": "Elk voorbeeld begint donker, vlak of korrelig, zoals een bestand recht uit de camera. Kies er een om te bewerken.",
    "tour2Title": "Licht",
    "tour2Body": "Belichting, contrast, hooglichten, schaduwen, witte en zwarte tinten. Sleep een schuifregelaar of gebruik de pijltoetsen. Selecteer het getal om het te herstellen.",
    "tour3Title": "Kleur",
    "tour3Body": "Temperatuur en tint corrigeren een kleurzweem. Levendigheid versterkt eerst gedempte kleuren; verzadiging verandert ze allemaal.",
    "tour4Title": "Detail en ruis",
    "tour4Body": "Duidelijkheid voegt lokaal contrast toe. Ruisonderdrukking is hier een demo die overschakelt naar een vooraf gemaakte, schonere afbeelding, niet de ruisonderdrukking van InFlight.",
    "tour5Title": "Maskeren",
    "tour5Body": "Selecteer het onderwerp en bewerk dan alleen het onderwerp of alleen de achtergrond. Het masker is voor elk voorbeeld vooraf gemaakt om te laten zien hoe onderwerpselectie werkt.",
    "tour6Title": "Bijsnijden en rechtzetten",
    "tour6Body": "Kies een vorm en zet de horizon recht.",
    "tour7Title": "Voor en na",
