    "matrixRowOnline": "Optionele online hulp, alleen als u daarvoor kiest",
    "matrixNote": "Basic verloopt nooit en heeft geen account nodig. Pro is een abonnement; als het eindigt, wordt het account weer Basic. Importeren, bewerken en exporteren worden nooit beperkt, niets wat je hebt gemaakt wordt ooit vergrendeld, en je originelen worden in geen enkele editie gewijzigd.",
    "proBody": "Pro voegt soortsuggesties, hulp bij het kiezen van foto’s en de optionele online helper toe. Het werkt offline: een apparaat dat niet kan controleren houdt Pro tot 30 dagen na de laatste controle, en tot 14 dagen na een verlengingsdatum.",
