    "skipToContent": "Naar de inhoud",
    "vizHeroLabel": "Een vergrote schets van de InFlight-editor. De aanwijzer sleept de schuif Schaduwen, daarna Belichting, en de foto wordt lichter. De wijziging staat in de geschiedenis, en daarna draait Ongedaan maken beide stappen terug.",
    "vizExposure": "Belichting",
    "vizVibrance": "Levendigheid",
    "vizOriginal": "Het origineel verandert nooit",
    "vizImportLabel": "De aanwijzer sleept drie fotobestanden naar InFlight. Bovenaan loopt een voortgangsbalk terwijl ze worden toegevoegd en de miniaturen verschijnen. De originele bestanden blijven waar ze zijn.",
    "vizDrop": "Zet hier foto's of een map neer",
    "vizAdded": "24 foto's toegevoegd",
    "vizCullLabel": "Zes foto's in een raster, geselecteerd met het toetsenbord. F markeert de eerste, 4 geeft de tweede vier sterren, X wijst de vierde af en F markeert de vijfde. De derde, waarover InFlight twijfelde, blijft gemarkeerd als Te beoordelen in plaats van te worden weggegooid.",
    "vizRejected": "Afgewezen",
    "vizEditLabel": "De aanwijzer zet Levendigheid omhoog en Hooglichten omlaag, en de foto verandert. Daarna wordt twee keer op Ongedaan maken gedrukt, en de foto is weer precies zoals hij was.",
    "vizExportLabel": "Een exportvenster voor 24 foto's, op volledig formaat, als JPEG. De aanwijzer drukt op Exporteren, een voortgangsbalk loopt vol en het venster meldt dat alle 24 zijn opgeslagen.",
