    "vizSaved": "24 opgeslagen",
    "vizModesLabel": "Drie vliegmodi naast elkaar: Solo, Copiloot en Automatische piloot. De aanwijzer kiest ze om de beurt en een eenvoudige zin eronder zegt wat die modus doet.",
    "vizStar": "Ster",
