    "vizYourStudio": "Jouw studio",
    "vizBrandKit": "Huisstijlset",
    "rawFuji": "Fujifilm (de meeste camera's)",
    "rawTitle": "Opent RAW-bestanden van",
    "rawListLabel": "Cameramerken waarvan de RAW-bestanden getest zijn",
    "rawAlso": "Opent ook RAW-bestanden van Samsung, Hasselblad, Phase One, Leica en Leaf. Die zijn nieuw, dus nog niet elk model is getest.",
    "matrixCloudBasic": "Niet inbegrepen",
    "matrixCloudPro": "500 per maand",
    "matrixRowCloudRunner": "Bewerkingen in de cloud, als je bent aangemeld: sommige zware stappen (nu klassieke ruisonderdrukking en opschalen) draaien in de cloud, en de verstuurde kopie wordt na elke run verwijderd",
    "matrixStoragePro": "2,5 GB",
    "matrixRowStorage": "Cloudopslag, om je foto’s op je andere apparaten te openen",
    "navHow": "Hoe het werkt",
    "navShoot": "Tijdens een shoot",
    "navPlans": "Abonnementen",
    "signIn": "Inloggen",
    "heroHeadline": "Een shoot selecteren, bewerken en delen. Ook zonder bereik.",
    "heroLeadNew": "InFlight sorteert een shoot, bewerkt hem en exporteert hem in elk formaat waarin je post, en komt nooit aan je originelen. Elke bewerking kan ongedaan worden gemaakt, en de Mac- en Windows-apps werken volledig offline, zonder account.",
    "welcomeTitle": "Welkom bij InFlight",
    "inviteOnly": "Alleen op uitnodiging zolang we testen.",
    "platformsNote": "InFlight is er voor macOS, Windows, Linux, iOS en Android, zonder webeditor. Een platform heeft alleen een download als de knop hieronder verschijnt; de rest komt binnenkort. Het werkt offline, zonder account.",
    "requestInvite": "Uitnodiging aanvragen",
    "promiseLabel": "Wat InFlight belooft",
    "promiseAiTitle": "Geen gegenereerde pixels.",
    "promiseAiBody": "InFlight verzint of vervangt nooit wat er in je foto staat, en schrijft nooit door een model gemaakte inhoud in de metadata van je bestanden. Je originelen worden nooit gewijzigd. Modellen meten en stellen voor (onderwerp, scherpte, soort, ruis). Ruisonderdrukking en verscherpen werken met de eigen pixels van je foto; de optionele aangeleerde ruisonderdrukking maakt alleen de pixels schoon die er al zijn, en wordt alleen gebruikt als een controle laat zien dat echt detail behouden blijft. De enige uitzondering is Vlekken herstellen, dat kopieert van een andere plek in je eigen foto, en alleen waar jij het zelf plaatst.",
    "promiseYoursTitle": "Je foto's blijven van jou.",
    "promiseYoursBody": "Originelen worden nooit gewijzigd of verplaatst, en er wordt niets geüpload tenzij je zelf kiest om te delen.",
    "promiseSocialTitle": "Eenvoudig delen op sociale media.",
    "promiseSocialBody": "Eén bewerking exporteert elke uitsnede en elk formaat dat je post, klaar voor elk platform.",
    "promiseCollabTitle": "Hulp uit de cloud, wanneer je wilt.",
    "promiseCollabBody": "Stuur foto’s voor bewerking in de cloud als je apparaat hulp nodig heeft: 500 per maand met Pro, 5.000 met Pro Plus, daarna 0,3p per stuk van je cloudtegoed. De verstuurde kopie wordt na elke run verwijderd. Pro bewaart ook 2,5 GB gekozen foto’s in de cloud, om te openen op je andere apparaten.",
    "whyTitle": "Waarom fotografen overstappen op InFlight",
    "why3Title": "Dezelfde app op elk apparaat",
    "why3Body": "Mac, Windows en Linux delen dezelfde schermen, en de apps voor iPhone, iPad en Android, die nog komen, worden met dezelfde code gebouwd, zodat u niets twee keer hoeft te leren.",
    "why4Title": "Eerlijk over je foto's",
    "why4Body": "Geen gegenereerde pixels en geen verzonnen details. Twijfelt het over een soort of een kleur, dan zegt het dat, in woorden, nooit alleen met kleur.",
    "howTitle": "Hoe het werkt",
    "how1Title": "1. Haal je foto's binnen",
    "how1Body": "Wijs InFlight een kaart of map aan. Het koppelt je originelen en verplaatst, hernoemt of overschrijft ze nooit.",
    "how2Title": "2. Bewaar de beste, rustig",
    "how2Body": "Markeer, beoordeel en vergelijk. Twijfelachtige foto's worden bewaard om te beoordelen, nooit voor je weggegooid.",
    "how3Title": "3. Bewerk, en maak alles ongedaan",
    "how3Body": "Elke wijziging is een recept dat je stap voor stap kunt terugdraaien. Tools op het apparaat werken offline, zonder iets te uploaden.",
    "how4Title": "4. Exporteer en deel",
    "how4Body": "Exports op volle grootte, klaar voor print, het web of sociale media.",
