    "heroTitle": "Più tempo dietro l’obiettivo.",
    "heroLead": "InFlight è uno spazio di lavoro per importare, selezionare, modificare ed esportare foto. Vuole rendere la modifica più rapida e più facile da capire: trova le tue foto migliori, fai poche modifiche chiare ed esporta.",
