    "rawAlso": "Apre anche i file RAW di Samsung, Hasselblad, Phase One, Leica e Leaf. Sono una novità, quindi non tutti i corpi sono ancora stati testati.",
    "matrixCloudBasic": "Non incluso",
    "matrixCloudPro": "500 al mese",
    "matrixRowCloudRunner": "Modifiche nel cloud, con l’accesso: alcuni passaggi pesanti (oggi riduzione del rumore classica e ingrandimento) si fanno nel cloud, e la copia inviata viene eliminata dopo ogni elaborazione",
    "matrixStoragePro": "2,5 GB",
    "matrixRowStorage": "Spazio cloud, per aprire le tue foto sugli altri tuoi dispositivi",
    "navHow": "Come funziona",
    "navShoot": "Durante un servizio",
    "navPlans": "Piani",
    "signIn": "Accedi",
    "heroHeadline": "Seleziona, modifica e condividi un servizio. Anche senza campo.",
    "heroLeadNew": "InFlight ordina uno shooting, lo modifica e lo esporta in ogni formato in cui pubblichi, e non tocca mai i tuoi originali. Ogni modifica si può annullare, e le app per Mac e Windows funzionano completamente offline, senza account.",
    "welcomeTitle": "Benvenuto in InFlight",
    "inviteOnly": "Solo su invito durante i test.",
    "platformsNote": "InFlight è pensato per macOS, Windows, Linux, iOS e Android, senza un editor web. Una piattaforma ha un download solo quando il suo pulsante compare qui sotto; le altre arrivano presto. Funziona offline, senza account.",
    "requestInvite": "Richiedi un invito",
    "promiseLabel": "Le promesse di InFlight",
    "promiseAiTitle": "Nessun pixel generato.",
    "promiseAiBody": "InFlight non inventa né sostituisce mai ciò che c’è nella tua foto, e non scrive mai contenuti prodotti da un modello nei metadati dei tuoi file. I tuoi originali non vengono mai modificati. I modelli misurano e suggeriscono (soggetto, messa a fuoco, specie, rumore). Riduzione del rumore e nitidezza lavorano sui pixel della tua foto; la riduzione del rumore appresa, facoltativa, pulisce solo i pixel già presenti, e si usa solo se un controllo mostra che il dettaglio reale resta. L’unica eccezione è Correzione macchie, che copia da un altro punto della tua stessa foto, e solo dove la metti tu.",
    "promiseYoursTitle": "Le tue foto restano tue.",
    "promiseYoursBody": "Gli originali non vengono mai modificati né spostati, e nulla viene caricato a meno che tu non scelga di condividere.",
    "promiseSocialTitle": "Condividi sui social con facilità.",
    "promiseSocialBody": "Una sola modifica esporta ogni ritaglio e formato che pubblichi, pronto per ogni piattaforma.",
    "promiseCollabTitle": "L’aiuto del cloud, quando vuoi.",
    "promiseCollabBody": "Invia foto da modificare nel cloud quando il tuo dispositivo ha bisogno di una mano: 500 al mese con Pro, 5.000 con Pro Plus, poi 0,3 p ciascuna dal credito cloud. La copia inviata viene eliminata dopo ogni elaborazione. Pro conserva anche 2,5 GB di foto scelte nel cloud, da aprire sugli altri tuoi dispositivi.",
    "whyTitle": "Perché i fotografi passano a InFlight",
    "why3Title": "La stessa app su ogni dispositivo",
    "why3Body": "Mac, Windows e Linux condividono le stesse schermate, e le app per iPhone, iPad e Android, ancora in arrivo, saranno costruite dallo stesso codice, così non c'è nulla da imparare due volte.",
    "why4Title": "Onesto sulle tue foto",
    "why4Body": "Nessun pixel generato e nessun dettaglio inventato. Quando non è sicuro di una specie o di un colore, lo dice, a parole, mai solo con il colore.",
    "howTitle": "Come funziona",
    "how1Title": "1. Porta dentro le tue foto",
    "how1Body": "Indica a InFlight una scheda o una cartella. Collega i tuoi originali e non li sposta, rinomina o riscrive mai.",
    "how2Title": "2. Tieni le migliori, con calma",
    "how2Body": "Contrassegna, valuta e confronta. Le foto incerte vengono tenute da rivedere, mai buttate al posto tuo.",
    "how3Title": "3. Modifica e annulla tutto",
    "how3Body": "Ogni modifica è una ricetta che puoi ripercorrere all'indietro. Gli strumenti sul dispositivo funzionano offline, senza caricare nulla.",
    "how4Title": "4. Esporta e condividi",
    "how4Body": "Esportazioni a grandezza piena, pronte per la stampa, il web o i social.",
    "shootTitle": "Pensato anche per il servizio",
    "shootModesTitle": "Modalità di volo",
    "shootModesBody": "Scegli quanto fa InFlight per te, progetto per progetto. Funziona sul tuo dispositivo, e nulla cambia senza un modo chiaro per tornare indietro.",
    "shootBrandTitle": "Il tuo marchio su ogni esportazione",
    "shootBrandBody": "Salva un kit del marchio una volta. Poi Esporta mette logo, colori e stile del testo su ogni foto in un solo passaggio. Resta sul tuo dispositivo.",
    "insideTitle": "Cosa contiene",
    "inCullTitle": "Selezione intelligente",
    "inSubjectTitle": "Riconoscimento del soggetto",
    "inSubjectBody": "Dà il nome alle specie di uccelli e riconosce aerei e veicoli, così puoi cercare un servizio in base al contenuto. Quando non è sicuro, lo dice.",
    "inSocialTitle": "Formati per i social",
    "inSocialBody": "Imposta una volta i ritagli e i formati che pubblichi. Poi una sola modifica si esporta in ogni formato, ciascuno con il suo ritaglio.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Note sul colore misurate sulla foto stessa, non sul tuo schermo, e spiegate con parole semplici. I fotografi daltonici modificano con fiducia.",
    "inMaskTitle": "Maschere, prima e dopo, riduzione del rumore",
    "inMaskBody": "Regola solo una parte della foto, confronta prima e dopo, e pulisci il rumore. Non si genera nulla: nessun pixel inventato.",
    "inOverlayTitle": "Sovrapposizioni e filigrane personalizzate",
    "inOverlayBody": "Salva logo, colori e stile del testo come kit del marchio, ed Esporta li mette su ogni foto in un solo passaggio.",
    "whoTitle": "Per chi è",
    "whoBody": "Chiunque: principianti, professionisti o solo per divertimento. Ogni strumento sul dispositivo è gratuito, senza limiti.",
