    "languageLabel": "Idioma",
    "heroTitle": "Mais tempo atrás da câmara.",
    "heroLead": "O InFlight é um espaço de trabalho para importar, selecionar, editar e exportar fotografias. Pretende tornar a edição mais rápida e mais fácil de perceber: encontre as suas melhores fotos, faça algumas edições que consiga acompanhar e exporte.",
    "heroDownloads": "Ver transferências",
    "heroPricing": "Ver preços",
    "aimsTitle": "O que o InFlight pretende fazer",
    "aimOfflineTitle": "Trabalhar offline",
    "aimOfflineBody": "Importe, selecione, edite e exporte sem ligação à internet nem conta. As suas fotos ficam no seu dispositivo ou no armazenamento que escolher.",
    "aimOriginalsTitle": "Nunca alterar os seus originais",
    "aimOriginalsBody": "O InFlight não altera, move nem substitui um ficheiro original. As edições são guardadas como passos que pode alterar ou anular a qualquer momento.",
    "aimCalmTitle": "Ser calmo e acessível",
    "aimCalmBody": "Um ecrã tranquilo, palavras simples, acesso total pelo teclado e movimento reduzido. Nada depende só da cor. Foi pensado para fotógrafos daltónicos, com PHDA e autistas.",
    "aimHonestTitle": "Ser honesto sobre o que sabe",
    "aimHonestBody": "Quando o InFlight não tem a certeza, di-lo. Avisa quando mostra a pré-visualização incorporada de um ficheiro RAW, nunca inventa detalhe e guarda as fotos incertas para rever, em vez de as rejeitar.",
    "aimHelpTitle": "Ajudar sem tomar conta",
    "aimHelpBody": "A aprendizagem automática pode ajudar a reduzir o ruído, encontrar um motivo ou sugerir uma máscara. Cabe-lhe a si verificar e ajustar cada sugestão.",
    "aimSameTitle": "Funcionar igual em todo o lado",
    "aimSameBody": "As mesmas ferramentas e a mesma forma de trabalhar em macOS, Windows e Linux, com iPhone, iPad e Android a seguir.",
    "aimOnceTitle": "Sem amarras",
