    "chooseSubBody": "Pague por mês ou por ano e cancele quando quiser. Se parar, a sua conta volta ao Basic, que é gratuito: os seus projetos, edições e exportações nunca ficam bloqueados.",
    "choosePricePromise": "Promessa de preço: o preço da subscrição nunca sobe sem pelo menos 30 dias de aviso por email, e um novo preço só começa numa renovação após esse aviso. Pode cancelar antes.",
    "chooseBuyHow": "Para subscrever, inicie sessão na aplicação InFlight e escolha Subscrever o Pro. A Paddle, o nosso revendedor, trata do pagamento.",
