    "privacyTitle": "As suas fotografias continuam a ser suas",
    "privacyBody": "O InFlight funciona primeiro no local. Importe, selecione e edite sem conta. A análise online opcional ou futuras funcionalidades na nuvem têm de ser ativadas de propósito. Os seus originais não são carregados sem aviso.",
