    "footerText": "InFlight · Pré-lançamento",
    "footerReport": "Comunicar um problema",
    "demoDisclaimer": "<strong>Isto é uma demonstração das ferramentas, não a aplicação completa.</strong> Usa pequenas imagens de exemplo e uma pré-visualização simplificada, não o motor RAW do InFlight. A redução de ruído e a seleção do motivo são mostradas com versões preparadas de antemão de cada exemplo.",
    "installMac": "Abra a imagem de disco transferida e arraste o InFlight para Aplicações. Na primeira vez, clique com o botão direito no InFlight, escolha <strong>Abrir</strong> e depois <strong>Abrir</strong> outra vez.",
    "installWindows": "Execute o instalador. Se o Windows disser que protegeu o seu PC, escolha <strong>Mais informações</strong> e depois <strong>Executar mesmo assim</strong>.",
    "pricingIntro": "<strong>O Basic é gratuito para sempre.</strong> O Pro é uma subscrição, paga por mês ou por ano. Subscreve a partir da aplicação InFlight; este site não recebe pagamentos diretamente.",
    "reqMac": "<strong>macOS:</strong> a confirmar quando a primeira versão for testada em Macs reais (feita para Apple silicon e Intel).",
    "reqWindows": "<strong>Windows:</strong> a confirmar quando a primeira versão for testada em PCs reais.",
    "reqStorage": "<strong>Armazenamento:</strong> espaço para o modelo opcional de espécies no dispositivo (cerca de 90 MB) e o seu catálogo. Os originais podem ficar em discos externos.",
    "startImport": "<strong>Importar:</strong> escolha fotografias ou uma pasta guardada no seu dispositivo. Mantenha uma cópia de segurança separada dos seus originais.",
    "startCull": "<strong>Selecionar:</strong> reveja as fotografias, marque Manter ou Rejeitar e compare fotogramas vizinhos.",
    "startEdit": "<strong>Editar:</strong> ajuste a luz, a cor e os recortes. As edições são reversíveis e não reescrevem o ficheiro original.",
    "startExport": "<strong>Exportar:</strong> escolha um formato e guarde a fotografia processada.",
    "nikonNote": "<strong>Nota sobre RAW Nikon:</strong> no navegador, os ficheiros NEF usam, por agora, as pré-visualizações incorporadas. A descodificação RAW em resolução total, incluindo as variantes Nikon High Efficiency, tem de ser validada nas versões nativas antes de ser anunciada como suportada.",
    "devicesAnywhere": "<strong>Guarde as fotos onde quiser:</strong> em qualquer disco, num NAS ou numa pasta sincronizada pelo iCloud Drive, Dropbox ou OneDrive. O InFlight nunca move nem altera os seus originais.",
    "devicesCopy": "<strong>Copiar definições para outro dispositivo:</strong> escolha <em>Guardar ficheiro de definições</em> e guarde-o no iCloud Drive; depois escolha <em>Carregar ficheiro de definições</em> no seu outro Mac, PC ou telemóvel.",
