    "signIn": "Iniciar sessão",
    "heroHeadline": "Selecione, edite e partilhe uma sessão. Mesmo sem rede.",
    "heroLeadNew": "O InFlight organiza uma sessão, edita-a e exporta-a em cada tamanho em que publica, e nunca toca nos seus originais. Todas as edições podem ser anuladas, e as aplicações para Mac e Windows funcionam totalmente offline, sem conta.",
    "welcomeTitle": "Bem-vindo ao InFlight",
    "inviteOnly": "Apenas por convite durante os testes.",
    "platformsNote": "O InFlight é para macOS, Windows, Linux, iOS e Android, sem editor web. Uma plataforma só tem transferência quando o seu botão aparece abaixo; as restantes chegam em breve. Funciona offline, sem conta.",
    "requestInvite": "Pedir um convite",
    "promiseLabel": "O que o InFlight promete",
    "promiseAiTitle": "Sem píxeis gerados.",
    "promiseAiBody": "A InFlight nunca inventa nem substitui o que está na sua fotografia, e nunca escreve conteúdo feito por um modelo nos metadados dos seus ficheiros. Os seus originais nunca são alterados. Os modelos medem e sugerem (motivo, foco, espécie, ruído). A redução de ruído e a nitidez trabalham com os próprios píxeis da sua fotografia; a redução de ruído aprendida, opcional, só limpa os píxeis que já lá estão, e só é usada se uma verificação mostrar que o detalhe real se mantém. A única exceção é a Correção de manchas, que copia de outro ponto da sua própria fotografia, e só onde a coloca.",
    "promiseYoursTitle": "As suas fotos continuam a ser suas.",
    "promiseYoursBody": "Os originais nunca são alterados nem movidos, e nada é enviado a não ser que escolha partilhar.",
    "promiseSocialTitle": "Partilhe nas redes com facilidade.",
    "promiseSocialBody": "Uma única edição exporta todos os recortes e tamanhos que publica, prontos para cada plataforma.",
    "promiseCollabTitle": "Ajuda na nuvem, quando quiser.",
    "promiseCollabBody": "Envie fotografias para edição na nuvem quando o seu dispositivo precisar de ajuda: 500 por mês com Pro, 5.000 com Pro Plus, depois 0,3 p cada do crédito na nuvem. A cópia enviada é apagada após cada execução. O Pro guarda também 2,5 GB de fotografias escolhidas na nuvem, para abrir nos seus outros dispositivos.",
    "whyTitle": "Porque é que os fotógrafos mudam para o InFlight",
    "why3Title": "A mesma aplicação em todos os dispositivos",
    "why3Body": "Mac, Windows e Linux partilham os mesmos ecrãs, e as aplicações para iPhone, iPad e Android, que ainda vão chegar, serão feitas a partir do mesmo código, por isso nada precisa de ser aprendido duas vezes.",
    "why4Title": "Honesto sobre as suas fotos",
    "why4Body": "Sem píxeis gerados e sem detalhes inventados. Quando não tem a certeza de uma espécie ou de uma cor, di-lo, por palavras, nunca só com cor.",
    "howTitle": "Como funciona",
    "how1Title": "1. Traga as suas fotos",
    "how1Body": "Indique ao InFlight um cartão ou uma pasta. Liga-se aos seus originais e nunca os move, renomeia ou reescreve.",
    "how2Title": "2. Fique com as melhores, com calma",
    "how2Body": "Marque, classifique e compare. As fotos duvidosas ficam guardadas para rever, nunca deitadas fora por si.",
    "how3Title": "3. Edite e anule tudo",
    "how3Body": "Cada alteração é uma receita que pode percorrer para trás. As ferramentas no dispositivo funcionam offline, sem enviar nada.",
    "how4Title": "4. Exporte e partilhe",
    "how4Body": "Exportações em tamanho real, prontas para imprimir, para a web ou para as redes sociais.",
    "shootTitle": "Feito também para a sessão",
    "shootModesTitle": "Modos de voo",
    "shootModesBody": "Escolha quanto o InFlight faz por si, projeto a projeto. Funciona no seu dispositivo, e nada muda sem uma forma clara de voltar atrás.",
    "shootBrandTitle": "A sua marca em cada exportação",
    "shootBrandBody": "Guarde um kit de marca uma vez. Depois, Exportar coloca o logótipo, as cores e o estilo de texto em cada foto num só passo. Fica no seu dispositivo.",
    "insideTitle": "O que inclui",
    "inCullTitle": "Seleção inteligente",
    "inSubjectTitle": "Identificação do motivo",
    "inSubjectBody": "Dá nome às espécies de aves e identifica aviões e veículos, para pesquisar uma sessão pelo que contém. Quando não tem a certeza, di-lo.",
    "inSocialTitle": "Formatos para redes sociais",
    "inSocialBody": "Defina uma vez os recortes e tamanhos que publica. Depois, uma única edição é exportada para cada formato, cada um com o seu recorte.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Notas de cor medidas na própria foto, não no seu ecrã, e explicadas em palavras simples. Os fotógrafos daltónicos editam com confiança.",
    "inMaskTitle": "Máscaras, antes e depois, redução de ruído",
    "inMaskBody": "Ajuste só uma parte da foto, compare antes e depois, e limpe o ruído. Nada é gerado: nenhum píxel inventado.",
    "inOverlayTitle": "Sobreposições e marcas de água próprias",
    "inOverlayBody": "Guarde o seu logótipo, cores e estilo de texto como kit de marca, e Exportar coloca-os em cada foto num só passo.",
