    "nikonNote": "<strong>Om Nikon RAW:</strong> I browseren bruger NEF-filer i øjeblikket indbyggede forhåndsvisninger. RAW-afkodning i fuld opløsning, også Nikon High Efficiency-varianter, skal valideres i de native versioner, før den kan kaldes understøttet.",
    "devicesAnywhere": "<strong>Gem fotos hvor som helst:</strong> på ethvert drev, en NAS eller en mappe, som iCloud Drive, Dropbox eller OneDrive synkroniserer. InFlight flytter eller ændrer aldrig dine originaler.",
    "devicesCopy": "<strong>Kopiér indstillinger til en anden enhed:</strong> vælg <em>Gem indstillingsfil</em>, og gem den i iCloud Drive. Vælg derefter <em>Indlæs indstillingsfil</em> på din anden Mac, pc eller telefon.",
