    "signIn": "Log ind",
    "heroHeadline": "Sortér, redigér og del en fotosession. Også uden signal.",
    "heroLeadNew": "InFlight sorterer en optagelse, redigerer den og eksporterer den i hver størrelse, du poster i, og rører aldrig dine originaler. Alle redigeringer kan fortrydes, og apps til Mac og Windows virker helt offline, uden konto.",
    "welcomeTitle": "Velkommen til InFlight",
    "inviteOnly": "Kun for inviterede, mens vi tester.",
    "platformsNote": "InFlight er til macOS, Windows, Linux, iOS og Android og har ingen webeditor. En platform har kun en download, når dens knap vises nedenfor; resten kommer snart. Det virker offline, uden konto.",
    "requestInvite": "Anmod om en invitation",
    "promiseLabel": "Det lover InFlight",
    "promiseAiTitle": "Ingen genererede pixels.",
    "promiseAiBody": "InFlight finder aldrig på eller erstatter det, der er i dit billede, og skriver aldrig indhold lavet af en model i dine filers metadata. Dine originaler ændres aldrig. Modeller måler og foreslår (motiv, fokus, art, støj). Støjreduktion og skarphed arbejder ud fra dit billedes egne pixels; den valgfrie lærte støjreduktion renser kun de pixels, der allerede er der, og bruges kun, når en kontrol viser, at de ægte detaljer er bevaret. Den eneste undtagelse er Pletfjernelse, som kopierer fra et andet sted i dit eget billede, og kun hvor du selv sætter den.",
    "promiseYoursTitle": "Dine billeder forbliver dine.",
    "promiseYoursBody": "Originaler ændres eller flyttes aldrig, og intet uploades, medmindre du vælger at dele.",
    "promiseSocialTitle": "Del nemt på sociale medier.",
    "promiseSocialBody": "Én redigering eksporterer alle de beskæringer og størrelser, du poster i, klar til hver platform.",
    "promiseCollabTitle": "Hjælp fra skyen, når du vil.",
    "promiseCollabBody": "Send billeder til redigering i skyen, når din enhed har brug for hjælp: 500 om måneden med Pro, 5.000 med Pro Plus, derefter 0,3 p stykket fra din skykredit. Den sendte kopi slettes efter hver kørsel. Pro gemmer også 2,5 GB valgte billeder i skyen, så du kan åbne dem på dine andre enheder.",
    "whyTitle": "Derfor skifter fotografer til InFlight",
    "why3Title": "Samme app på alle enheder",
    "why3Body": "Mac, Windows og Linux deler de samme skærmbilleder, og apps til iPhone, iPad og Android, der endnu ikke er klar, bygges af den samme kode, så du ikke skal lære noget to gange.",
    "why4Title": "Ærlig om dine billeder",
    "why4Body": "Ingen genererede pixels og ingen opdigtede detaljer. Når den ikke er sikker på en art eller en farve, siger den det med ord, aldrig kun med farve.",
    "howTitle": "Sådan virker det",
    "how1Title": "1. Hent dine billeder ind",
    "how1Body": "Peg InFlight mod et kort eller en mappe. Den linker til dine originaler og flytter, omdøber eller overskriver dem aldrig.",
    "how2Title": "2. Behold de bedste, i ro",
    "how2Body": "Markér, bedøm og sammenlign. Usikre billeder gemmes til gennemsyn og smides aldrig ud for dig.",
    "how3Title": "3. Redigér, og fortryd hvad som helst",
    "how3Body": "Hver ændring er en opskrift, du kan gå baglæns igennem. Værktøjer på enheden virker offline, uden at noget uploades.",
    "how4Title": "4. Eksportér og del",
    "how4Body": "Eksport i fuld størrelse, klar til tryk, nettet eller sociale medier.",
    "shootTitle": "Også lavet til selve sessionen",
    "shootModesTitle": "Flytilstande",
    "shootModesBody": "Vælg, hvor meget InFlight gør for dig, projekt for projekt. Det kører på din enhed, og intet ændres uden en klar vej tilbage.",
    "shootBrandTitle": "Dit brand på hver eksport",
    "shootBrandBody": "Gem et brandkit én gang. Eksportér sætter derefter logo, farver og tekststil på hvert billede i ét trin. Det bliver på din enhed.",
    "insideTitle": "Det er indeni",
    "inCullTitle": "Smart sortering",
    "inSubjectTitle": "Motivgenkendelse",
    "inSubjectBody": "Navngiver fuglearter og mærker fly og køretøjer, så du kan søge i en session efter indhold. Når den ikke er sikker, siger den det.",
    "inSocialTitle": "Formater til sociale medier",
    "inSocialBody": "Opsæt de beskæringer og størrelser, du poster i, én gang. Én redigering eksporteres derefter til hvert format med sin egen beskæring.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Farvenoter målt i selve billedet, ikke på din skærm, og forklaret med almindelige ord. Farveblinde fotografer kan redigere med selvtillid.",
    "inMaskTitle": "Masker, før og efter, støjfjernelse",
    "inMaskBody": "Justér kun en del af et billede, sammenlign før og efter, og fjern støj. Intet genereres: ingen opdigtede pixels.",
    "inOverlayTitle": "Egne overlejringer og vandmærker",
