    "startTitle": "Kom igång",
    "devicesTitle": "Dina foton, din lagring, dina enheter",
    "privacyTitle": "Dina fotografier förblir dina",
    "privacyBody": "InFlight arbetar lokalt först. Importera, gallra och redigera utan konto. Valfri onlineanalys eller framtida molnfunktioner måste slås på medvetet. Dina original laddas inte upp i tysthet.",
