    "footerText": "InFlight · Förhandsversion",
    "footerReport": "Rapportera ett problem",
    "demoDisclaimer": "<strong>Det här är en demo av verktygen, inte hela appen.</strong> Den använder små exempelbilder och en förenklad förhandsvisning, inte InFlights RAW-motor. Brusreducering och val av motiv visas med färdiga versioner av varje exempel.",
    "installMac": "Öppna den nedladdade skivavbildningen och dra InFlight till Program. Första gången högerklickar du på InFlight, väljer <strong>Öppna</strong> och sedan <strong>Öppna</strong> igen.",
    "installWindows": "Kör installationsprogrammet. Om Windows säger att datorn har skyddats väljer du <strong>Mer information</strong> och sedan <strong>Kör ändå</strong>.",
    "pricingIntro": "<strong>Basic är gratis för alltid.</strong> Pro är en prenumeration som betalas per månad eller per år. Du prenumererar i InFlight-appen; den här webbplatsen tar inte själv emot betalningar.",
    "reqMac": "<strong>macOS:</strong> bekräftas när den första versionen har testats på riktiga Mac-datorer (byggd för Apple silicon och Intel).",
    "reqWindows": "<strong>Windows:</strong> bekräftas när den första versionen har testats på riktiga PC-datorer.",
    "reqStorage": "<strong>Lagring:</strong> plats för den valfria artmodellen på enheten (cirka 90 MB) och din katalog. Original kan ligga kvar på externa enheter.",
    "startImport": "<strong>Importera:</strong> välj fotografier eller en mapp på din enhet. Ha en separat säkerhetskopia av dina original.",
    "startCull": "<strong>Gallra:</strong> granska fotografier, markera Behåll eller Avvisa och jämför närliggande bilder.",
    "startEdit": "<strong>Redigera:</strong> justera ljus, färg och beskärning. Redigeringar kan ångras och skriver inte över originalfilen.",
    "startExport": "<strong>Exportera:</strong> välj ett format och spara det färdiga fotografiet.",
    "nikonNote": "<strong>Om Nikon RAW:</strong> I webbläsaren använder NEF-filer för närvarande inbyggda förhandsvisningar. RAW-avkodning i full upplösning, även Nikon High Efficiency-varianter, måste valideras i de inbyggda apparna innan den kan sägas stödjas.",
    "devicesAnywhere": "<strong>Förvara foton var som helst:</strong> på vilken enhet som helst, en NAS eller en mapp som iCloud Drive, Dropbox eller OneDrive synkroniserar. InFlight flyttar eller ändrar aldrig dina original.",
    "devicesCopy": "<strong>Kopiera inställningar till en annan enhet:</strong> välj <em>Spara inställningsfil</em> och spara den i iCloud Drive. Välj sedan <em>Läs in inställningsfil</em> på din andra Mac, PC eller telefon.",
