    "signIn": "Logga in",
    "heroHeadline": "Gallra, redigera och dela en fotografering. Även utan täckning.",
    "heroLeadNew": "InFlight sorterar en fotosession, redigerar den och exporterar den i varje storlek du postar i, och rör aldrig dina original. Varje redigering kan ångras, och apparna för Mac och Windows fungerar helt offline, utan konto.",
    "welcomeTitle": "Välkommen till InFlight",
    "inviteOnly": "Endast för inbjudna medan vi testar.",
    "platformsNote": "InFlight finns för macOS, Windows, Linux, iOS och Android och har ingen webbredigerare. En plattform har bara en nedladdning när dess knapp visas nedan; resten kommer snart. Det fungerar offline, utan konto.",
    "requestInvite": "Be om en inbjudan",
    "promiseLabel": "Det här lovar InFlight",
    "promiseAiTitle": "Inga genererade pixlar.",
    "promiseAiBody": "InFlight hittar aldrig på eller ersätter det som finns i din bild, och skriver aldrig innehåll gjort av en modell i dina filers metadata. Dina original ändras aldrig. Modeller mäter och föreslår (motiv, fokus, art, brus). Brusreducering och skärpning utgår från bildens egna pixlar; den valfria inlärda brusreduceringen rengör bara de pixlar som redan finns, och används bara när en kontroll visar att verkliga detaljer finns kvar. Det enda undantaget är Fläckborttagning, som kopierar från ett annat ställe i din egen bild, och bara där du själv sätter den.",
    "promiseYoursTitle": "Dina bilder förblir dina.",
    "promiseYoursBody": "Original ändras eller flyttas aldrig, och inget laddas upp om du inte väljer att dela.",
    "promiseSocialTitle": "Dela enkelt i sociala medier.",
    "promiseSocialBody": "En redigering exporterar varje beskärning och storlek du publicerar i, redo för varje plattform.",
    "promiseCollabTitle": "Hjälp från molnet, när du vill.",
    "promiseCollabBody": "Skicka bilder för redigering i molnet när din enhet behöver hjälp: 500 i månaden med Pro, 5 000 med Pro Plus, sedan 0,3 p styck från din molnkredit. Den skickade kopian raderas efter varje körning. Pro sparar också 2,5 GB valda bilder i molnet, att öppna på dina andra enheter.",
    "whyTitle": "Därför byter fotografer till InFlight",
    "why3Title": "Samma app på alla enheter",
    "why3Body": "Mac, Windows och Linux delar samma skärmar, och apparna för iPhone, iPad och Android, som ännu inte är klara, byggs av samma kod, så du behöver inte lära dig något två gånger.",
    "why4Title": "Ärlig om dina bilder",
    "why4Body": "Inga genererade pixlar och inga påhittade detaljer. När den inte är säker på en art eller en färg säger den det, i ord, aldrig bara med färg.",
    "howTitle": "Så fungerar det",
    "how1Title": "1. Ta in dina bilder",
    "how1Body": "Peka InFlight mot ett kort eller en mapp. Den länkar till dina original och flyttar, byter namn på eller skriver aldrig över dem.",
    "how2Title": "2. Behåll de bästa, i lugn och ro",
    "how2Body": "Flagga, betygsätt och jämför. Osäkra bilder sparas för granskning och kastas aldrig åt dig.",
    "how3Title": "3. Redigera, och ångra vad som helst",
    "how3Body": "Varje ändring är ett recept som du kan stega bakåt genom. Verktyg på enheten fungerar offline, utan att något laddas upp.",
    "how4Title": "4. Exportera och dela",
    "how4Body": "Export i full storlek, klar för tryck, webben eller sociala medier.",
    "shootTitle": "Gjord för själva fotograferingen också",
    "shootModesTitle": "Flyglägen",
    "shootModesBody": "Välj hur mycket InFlight gör åt dig, projekt för projekt. Det körs på din enhet, och inget ändras utan en tydlig väg tillbaka.",
    "shootBrandTitle": "Ditt varumärke på varje export",
    "shootBrandBody": "Spara ett varumärkespaket en gång. Exportera lägger sedan logotyp, färger och textstil på varje bild i ett steg. Det stannar på din enhet.",
    "insideTitle": "Det här finns inuti",
    "inCullTitle": "Smart gallring",
    "inSubjectTitle": "Motivigenkänning",
    "inSubjectBody": "Namnger fågelarter och märker flygplan och fordon, så att du kan söka i en fotografering efter innehåll. När den inte är säker säger den det.",
    "inSocialTitle": "Format för sociala medier",
    "inSocialBody": "Ställ in beskärningar och storlekar du publicerar i, en gång. En redigering exporteras sedan till varje format, var och en med sin egen beskärning.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Färganteckningar mätta i själva bilden, inte på din skärm, och förklarade med enkla ord. Färgblinda fotografer kan redigera med självförtroende.",
    "inMaskTitle": "Masker, före och efter, brusreducering",
    "inMaskBody": "Justera bara en del av en bild, jämför före och efter, och rensa bort brus. Inget genereras: inga påhittade pixlar.",
    "inOverlayTitle": "Egna överlägg och vattenstämplar",
    "inOverlayBody": "Spara logotyp, färger och textstil som ett varumärkespaket, så lägger Exportera dem på varje bild i ett steg.",
