    "heroLead": "InFlight er et arbeidsområde for bilder der du importerer, sorterer, redigerer og eksporterer. Målet er å gjøre redigering raskere og lettere å forstå: finn dine beste bilder, gjør noen få redigeringer du kan følge, og eksporter.",
