    "privacyTitle": "Bildene dine forblir dine",
    "privacyBody": "InFlight er lokal først. Importer, sorter og rediger uten konto. Valgfri analyse på nett eller fremtidige skyfunksjoner må slås på med vilje. Originalene dine lastes ikke opp i det stille.",
