    "footerText": "InFlight · Forhåndsutgave",
    "footerReport": "Rapporter et problem",
    "demoDisclaimer": "<strong>Dette er en demo av verktøyene, ikke hele appen.</strong> Den bruker små eksempelbilder og en forenklet forhåndsvisning, ikke InFlights RAW-motor. Støyreduksjon og motivvalg vises med ferdiglagde versjoner av hvert eksempel.",
    "installMac": "Åpne diskbildet du lastet ned, og dra InFlight til Programmer. Første gang høyreklikker du på InFlight, velger <strong>Åpne</strong> og deretter <strong>Åpne</strong> igjen.",
    "installWindows": "Kjør installasjonsprogrammet. Hvis Windows sier at den beskyttet PC-en, velger du <strong>Mer informasjon</strong> og deretter <strong>Kjør likevel</strong>.",
    "pricingIntro": "<strong>Basic er gratis for alltid.</strong> Pro er et abonnement, betalt månedlig eller årlig. Du abonnerer fra InFlight-appen; dette nettstedet tar ikke imot betalinger selv.",
    "reqMac": "<strong>macOS:</strong> bekreftes når den første versjonen er testet på ekte Mac-maskiner (laget for Apple silicon og Intel).",
    "reqWindows": "<strong>Windows:</strong> bekreftes når den første versjonen er testet på ekte PC-er.",
    "reqStorage": "<strong>Lagring:</strong> plass til den valgfrie artsmodellen på enheten (omtrent 90 MB) og katalogen din. Originalene kan bli liggende på eksterne disker.",
    "startImport": "<strong>Import:</strong> velg bilder eller en mappe som er lagret på enheten din. Ha en egen sikkerhetskopi av originalene.",
    "startCull": "<strong>Sorter:</strong> se gjennom bildene, merk Behold eller Avvis, og sammenlign bilder tatt like etter hverandre.",
    "startEdit": "<strong>Rediger:</strong> juster lys, farge og beskjæring. Redigeringer kan angres og skriver ikke over originalfilen.",
    "startExport": "<strong>Eksporter:</strong> velg et format og lagre det ferdige bildet.",
    "nikonNote": "<strong>Om Nikon RAW:</strong> NEF-håndtering i nettleseren bruker foreløpig innebygde forhåndsvisninger. RAW-dekoding i full oppløsning, også for Nikon High Efficiency-varianter, må valideres i de native versjonene før den oppgis som støttet.",
    "devicesAnywhere": "<strong>Ha bildene hvor som helst:</strong> på en hvilken som helst disk, en NAS eller en mappe som iCloud Drive, Dropbox eller OneDrive synkroniserer. InFlight flytter eller endrer aldri originalene dine.",
    "devicesCopy": "<strong>Kopier innstillinger til en annen enhet:</strong> velg <em>Lagre innstillingsfil</em> og lagre den i iCloud Drive, og velg så <em>Last inn innstillingsfil</em> på den andre Mac-en, PC-en eller telefonen.",
