    "navPlans": "Planer",
    "signIn": "Logg inn",
    "heroHeadline": "Sorter, rediger og del en fotoøkt. Også uten dekning.",
    "heroLeadNew": "InFlight sorterer en fotoøkt, redigerer den og eksporterer den i hver størrelse du poster i, og rører aldri originalene dine. Alle redigeringer kan angres, og appene for Mac og Windows fungerer helt offline, uten konto.",
    "welcomeTitle": "Velkommen til InFlight",
    "inviteOnly": "Kun for inviterte mens vi tester.",
    "platformsNote": "InFlight er for macOS, Windows, Linux, iOS og Android og har ingen nettredigerer. En plattform har bare en nedlasting når knappen vises nedenfor; resten kommer snart. Det fungerer offline, uten konto.",
    "requestInvite": "Be om en invitasjon",
    "promiseLabel": "Dette lover InFlight",
    "promiseAiTitle": "Ingen genererte piksler.",
    "promiseAiBody": "InFlight dikter aldri opp eller erstatter det som er i bildet ditt, og skriver aldri innhold laget av en modell inn i filenes metadata. Originalene dine endres aldri. Modeller måler og foreslår (motiv, fokus, art, støy). Støyreduksjon og skarphet arbeider ut fra bildets egne piksler; den valgfrie lærte støyreduksjonen renser bare pikslene som allerede er der, og brukes bare når en kontroll viser at ekte detaljer er bevart. Det eneste unntaket er Flekkfjerning, som kopierer fra et annet sted i ditt eget bilde, og bare der du selv setter den.",
    "promiseYoursTitle": "Bildene dine forblir dine.",
    "promiseYoursBody": "Originaler endres eller flyttes aldri, og ingenting lastes opp med mindre du velger å dele.",
    "promiseSocialTitle": "Del enkelt i sosiale medier.",
    "promiseSocialBody": "Én redigering eksporterer hver beskjæring og størrelse du publiserer i, klar for hver plattform.",
    "promiseCollabTitle": "Hjelp fra skyen, når du vil.",
    "promiseCollabBody": "Send bilder til redigering i skyen når enheten din trenger hjelp: 500 i måneden med Pro, 5 000 med Pro Plus, deretter 0,3 p per stykk fra skykreditten. Den sendte kopien slettes etter hver kjøring. Pro lagrer også 2,5 GB valgte bilder i skyen, så du kan åpne dem på de andre enhetene dine.",
    "whyTitle": "Derfor bytter fotografer til InFlight",
    "why3Title": "Samme app på alle enheter",
    "why3Body": "Mac, Windows og Linux deler de samme skjermbildene, og appene for iPhone, iPad og Android, som ennå ikke er klare, bygges av samme kode, så du slipper å lære noe to ganger.",
    "why4Title": "Ærlig om bildene dine",
    "why4Body": "Ingen genererte piksler og ingen oppdiktede detaljer. Når den ikke er sikker på en art eller en farge, sier den det, med ord, aldri bare med farge.",
    "howTitle": "Slik fungerer det",
    "how1Title": "1. Hent inn bildene dine",
    "how1Body": "Pek InFlight mot et kort eller en mappe. Den lenker til originalene og flytter, gir nytt navn til eller overskriver dem aldri.",
    "how2Title": "2. Behold de beste, i ro og mak",
    "how2Body": "Merk, vurder og sammenlign. Usikre bilder tas vare på for gjennomgang og kastes aldri for deg.",
    "how3Title": "3. Rediger, og angre hva som helst",
    "how3Body": "Hver endring er en oppskrift du kan gå baklengs gjennom. Verktøy på enheten fungerer offline, uten at noe lastes opp.",
    "how4Title": "4. Eksporter og del",
    "how4Body": "Eksport i full størrelse, klar for trykk, nettet eller sosiale medier.",
    "shootTitle": "Laget for selve fotoøkten også",
    "shootModesTitle": "Flymoduser",
    "shootModesBody": "Velg hvor mye InFlight gjør for deg, prosjekt for prosjekt. Det kjører på enheten din, og ingenting endres uten en tydelig vei tilbake.",
    "shootBrandTitle": "Merkevaren din på hver eksport",
    "shootBrandBody": "Lagre et merkevaresett én gang. Eksporter legger så logo, farger og tekststil på hvert bilde i ett steg. Det blir på enheten din.",
    "insideTitle": "Dette er inni",
    "inCullTitle": "Smart sortering",
    "inSubjectTitle": "Motivgjenkjenning",
    "inSubjectBody": "Navngir fuglearter og merker fly og kjøretøy, så du kan søke i en fotoøkt etter innhold. Når den ikke er sikker, sier den det.",
    "inSocialTitle": "Formater for sosiale medier",
    "inSocialBody": "Sett opp beskjæringene og størrelsene du publiserer i, én gang. Én redigering eksporteres så til hvert format, hver med sin egen beskjæring.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Fargenotater målt i selve bildet, ikke på skjermen din, og forklart med enkle ord. Fargeblinde fotografer kan redigere med selvtillit.",
    "inMaskTitle": "Masker, før og etter, støyfjerning",
    "inMaskBody": "Juster bare en del av et bilde, sammenlign før og etter, og fjern støy. Ingenting genereres: ingen oppdiktede piksler.",
    "inOverlayTitle": "Egne overlegg og vannmerker",
