    "heroLeadNew": "InFlight lajittelee kuvauskeikan, muokkaa sen ja vie sen jokaiseen kokoon, jossa julkaiset, eikä koske koskaan alkuperäisiisi. Jokaisen muokkauksen voi kumota, ja Mac- ja Windows-sovellukset toimivat täysin offline, ilman tiliä.",
    "welcomeTitle": "Tervetuloa InFlightiin",
    "inviteOnly": "Vain kutsusta testauksen ajan.",
    "platformsNote": "InFlight on tarkoitettu macOS-, Windows-, Linux-, iOS- ja Android-laitteille, eikä siinä ole verkkoeditoria. Alustalla on lataus vain, kun sen painike näkyy alla; muut tulevat pian. Se toimii ilman verkkoyhteyttä ja tiliä.",
    "requestInvite": "Pyydä kutsua",
    "promiseLabel": "InFlightin lupaukset",
    "promiseAiTitle": "Ei generoituja pikseleitä.",
    "promiseAiBody": "InFlight ei koskaan keksi tai korvaa sitä, mitä kuvassasi on, eikä koskaan kirjoita mallin tuottamaa sisältöä tiedostojesi metatietoihin. Alkuperäisiä ei koskaan muuteta. Mallit mittaavat ja ehdottavat (kohde, tarkennus, laji, kohina). Kohinanpoisto ja terävöitys käyttävät kuvasi omia pikseleitä; valinnainen opittu kohinanpoisto vain puhdistaa jo olemassa olevat pikselit, ja sitä käytetään vain, jos tarkistus näyttää todellisten yksityiskohtien säilyneen. Ainoa poikkeus on Täplien korjaus, joka kopioi toisesta kohdasta omassa kuvassasi, ja vain sinne, mihin itse sen asetat.",
    "promiseYoursTitle": "Kuvasi pysyvät sinun.",
    "promiseYoursBody": "Alkuperäisiä ei koskaan muuteta eikä siirretä, eikä mitään ladata palvelimelle, ellet itse päätä jakaa.",
    "promiseSocialTitle": "Jaa helposti someen.",
    "promiseSocialBody": "Yksi muokkaus vie jokaisen rajauksen ja koon, joissa julkaiset, valmiina kullekin alustalle.",
    "promiseCollabTitle": "Apua pilvestä, kun haluat.",
    "promiseCollabBody": "Lähetä kuvia pilvimuokkaukseen, kun laitteesi tarvitsee apua: 500 kuukaudessa Prolla, 5 000 Pro Plussalla, sen jälkeen 0,3 p kappaleelta pilvisaldosta. Lähetetty kopio poistetaan jokaisen ajon jälkeen. Pro Plus säilyttää myös 2,5 Gt valittuja kuvia pilvessä, avattaviksi muilla laitteillasi.",
    "whyTitle": "Miksi kuvaajat vaihtavat InFlightiin",
    "why3Title": "Sama sovellus kaikilla laitteilla",
    "why3Body": "Macissa, Windowsissa ja Linuxissa on samat näkymät, ja iPhone-, iPad- ja Android-sovellukset, jotka ovat vasta tulossa, rakennetaan samasta koodista, joten mitään ei tarvitse oppia kahdesti.",
    "why4Title": "Rehellinen kuvistasi",
    "why4Body": "Ei generoituja pikseleitä eikä keksittyjä yksityiskohtia. Kun se ei ole varma lajista tai väristä, se sanoo sen sanoin, ei koskaan pelkällä värillä.",
    "howTitle": "Näin se toimii",
    "how1Title": "1. Tuo kuvasi",
    "how1Body": "Osoita InFlightille kortti tai kansio. Se linkittää alkuperäisiisi eikä koskaan siirrä, nimeä uudelleen tai kirjoita niitä yli.",
    "how2Title": "2. Pidä parhaat, rauhassa",
    "how2Body": "Merkitse, arvioi ja vertaa. Epävarmat kuvat säilytetään tarkistettaviksi, eikä niitä koskaan heitetä pois puolestasi.",
    "how3Title": "3. Muokkaa ja kumoa mitä tahansa",
    "how3Body": "Jokainen muutos on resepti, jota voit kulkea taaksepäin. Laitteella toimivat työkalut toimivat offline, mitään lataamatta.",
    "how4Title": "4. Vie ja jaa",
    "how4Body": "Täysikokoiset viennit, valmiina tulostukseen, verkkoon tai someen.",
    "shootTitle": "Tehty myös itse kuvaukseen",
    "shootModesTitle": "Lentotilat",
    "shootModesBody": "Valitse, kuinka paljon InFlight tekee puolestasi, projekti kerrallaan. Se toimii laitteellasi, eikä mikään muutu ilman selkeää paluutietä.",
    "shootBrandTitle": "Brändisi jokaiseen vientiin",
    "shootBrandBody": "Tallenna brändipaketti kerran. Vie lisää sitten logon, värit ja tekstityylin jokaiseen kuvaan yhdellä kertaa. Se pysyy laitteellasi.",
    "insideTitle": "Mitä sisältä löytyy",
    "inCullTitle": "Älykäs karsinta",
    "inSubjectTitle": "Kohteen tunnistus",
    "inSubjectBody": "Nimeää lintulajit ja merkitsee lentokoneet ja ajoneuvot, joten voit hakea kuvauksesta sisällön mukaan. Kun se ei ole varma, se sanoo sen.",
    "inSocialTitle": "Somemuodot",
    "inSocialBody": "Määritä kerran rajaukset ja koot, joissa julkaiset. Yksi muokkaus viedään sitten jokaiseen muotoon omalla rajauksellaan.",
    "inColourTitle": "ColourSense",
    "inColourBody": "Värihuomiot mitattuna itse kuvasta, ei näytöltäsi, ja kerrottuna selkein sanoin. Värisokeat kuvaajat voivat muokata luottavaisin mielin.",
    "inMaskTitle": "Maskit, ennen ja jälkeen, kohinanpoisto",
