    "footerReport": "Tilkynna vandamál",
    "demoDisclaimer": "<strong>Þetta er kynning á tólunum, ekki allt forritið.</strong> Hún notar litlar sýnismyndir og einfaldaða forskoðun, ekki RAW-vél InFlight. Suðeyðing og val á myndefni eru sýnd með fyrirfram gerðum útgáfum af hverju sýni.",
    "installMac": "Opnaðu diskmyndina sem þú sóttir og dragðu InFlight í Applications. Í fyrsta skipti skaltu hægrismella á InFlight, velja <strong>Open</strong> og svo aftur <strong>Open</strong>.",
