    "pricingIntro": "<strong>Basic er ókeypis til frambúðar.</strong> Pro er áskrift, greidd mánaðarlega eða árlega. Þú gerist áskrifandi í InFlight-forritinu; þessi vefur tekur ekki sjálfur við greiðslum.",
    "reqMac": "<strong>macOS:</strong> verður staðfest þegar fyrsta útgáfan hefur verið prófuð á raunverulegum Mac-tölvum (gerð fyrir Apple silicon og Intel).",
