    "startImport": "<strong>Innflutningur:</strong> veldu myndir eða möppu sem er geymd í tækinu þínu. Haltu sérstöku afriti af frumritunum.",
    "startCull": "<strong>Flokkun:</strong> farðu yfir myndirnar, merktu Halda eða Hafna og berðu saman myndir sem teknar voru hver á eftir annarri.",
