    "startExport": "<strong>Útflutningur:</strong> veldu snið og vistaðu fullunnu myndina.",
    "nikonNote": "<strong>Um Nikon RAW:</strong> Meðhöndlun NEF-skráa í vafranum byggir enn á innbyggðum forskoðunum. RAW-afkóðun í fullri upplausn, þar á meðal Nikon High Efficiency-afbrigði, þarf að staðfesta í innbyggðu útgáfunum áður en sagt er að hún sé studd.",
