    "heroHeadline": "Grisjaðu, breyttu og deildu myndatöku. Líka án sambands.",
    "heroLeadNew": "InFlight flokkar myndatöku, vinnur hana og flytur út í hverri stærð sem þú birtir í, og snertir aldrei frummyndirnar þínar. Allar breytingar má afturkalla og forritin fyrir Mac og Windows virka algjörlega án nettengingar, án aðgangs.",
    "welcomeTitle": "Velkomin í InFlight",
    "inviteOnly": "Aðeins fyrir boðsgesti á meðan við prófum.",
    "platformsNote": "InFlight er fyrir macOS, Windows, Linux, iOS og Android og hefur engan vefritil. Kerfi hefur aðeins niðurhal þegar hnappurinn birtist hér að neðan; hin koma fljótlega. Það virkar án nettengingar og án aðgangs.",
    "requestInvite": "Biðja um boð",
    "promiseLabel": "Það sem InFlight lofar",
    "promiseAiTitle": "Engir myndaðir dílar.",
    "promiseAiBody": "InFlight býr aldrei til eða kemur í stað þess sem er í myndinni þinni, og skrifar aldrei efni frá líkani í lýsigögn skránna þinna. Frummyndunum er aldrei breytt. Líkön mæla og stinga upp á (myndefni, fókus, tegund, suð). Suðeyðing og skerpa vinna úr eigin dílum myndarinnar; valfrjálsa lærða suðeyðingin hreinsar aðeins dílana sem eru þar fyrir, og er aðeins notuð ef athugun sýnir að raunveruleg smáatriði haldist. Eina undantekningin er Blettahreinsun, sem afritar af öðrum stað í þinni eigin mynd, og aðeins þar sem þú setur hana sjálf.",
    "promiseYoursTitle": "Myndirnar þínar eru áfram þínar.",
    "promiseYoursBody": "Frummyndum er aldrei breytt eða þær færðar og ekkert er hlaðið upp nema þú veljir að deila.",
    "promiseSocialTitle": "Deildu auðveldlega á samfélagsmiðlum.",
    "promiseSocialBody": "Ein breyting flytur út hverja skurð og stærð sem þú birtir í, tilbúna fyrir hvern miðil.",
    "promiseCollabTitle": "Hjálp úr skýinu, þegar þú vilt.",
    "promiseCollabBody": "Sendu myndir í vinnslu í skýinu þegar tækið þitt þarf hjálp: 500 á mánuði með Pro, 5.000 með Pro Plus, svo 0,3 p stykkið af skýjainneign. Afritinu sem var sent er eytt eftir hverja keyrslu. Pro geymir líka 2,5 GB af völdum myndum í skýinu, til að opna á öðrum tækjum þínum.",
    "whyTitle": "Af hverju ljósmyndarar skipta yfir í InFlight",
    "why3Title": "Sama forrit á öllum tækjum",
    "why3Body": "Mac, Windows og Linux deila sömu skjámyndum, og forritin fyrir iPhone, iPad og Android, sem eru væntanleg, verða smíðuð úr sama kóða, svo ekkert þarf að læra tvisvar.",
    "why4Title": "Heiðarlegt um myndirnar þínar",
    "why4Body": "Engir myndaðir dílar og engin uppdiktuð smáatriði. Þegar það er ekki visst um tegund eða lit segir það það, með orðum, aldrei aðeins með lit.",
    "howTitle": "Svona virkar það",
    "how1Title": "1. Komdu með myndirnar þínar",
    "how1Body": "Beindu InFlight að korti eða möppu. Það tengist frummyndunum þínum og færir þær aldrei, endurnefnir né skrifar yfir þær.",
