    "how3Body": "Hver breyting er uppskrift sem þú getur farið aftur í gegnum. Verkfæri í tækinu virka án nettengingar, án þess að neitt sé hlaðið upp.",
    "how4Title": "4. Flyttu út og deildu",
    "how4Body": "Útflutningur í fullri stærð, tilbúinn til prentunar, fyrir vefinn eða samfélagsmiðla.",
